INSERT INTO "public"."akha_news" ("id", "title", "slug", "excerpt", "content", "cover_image_url", "category", "tags", "author_id", "read_time_minutes", "is_published", "is_featured", "published_at", "created_at", "updated_at", "seo_title", "seo_description", "seo_keywords", "seo_robots", "og_image", "audio_asset_id", "subtitle", "json_ld", "access_level") VALUES
	('1fad1aa7-a79d-4d5a-8e56-f8d7cba4cc21', 'The Swing Festival: Women''s New Year', 'swing-festival-yehkuja', 'Why do we build a giant swing every August? Discover the meaning of Yehkuja and how it honors the goddess of fertility.', 'The Swing Festival, known as Yehkuja, is a four-day ritual held in late August. It is often called the Women''s New Year...', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/news/News_01_2026.webp', 'culture', '{festival,tradition,women}', NULL, 6, true, true, '2026-02-13 09:00:54.263747+00', '2026-02-15 09:00:54.263747+00', '2026-02-15 09:00:54.263747+00', 'The Swing Festival: Women''s New Year', 'Why do we build a giant swing every August? Discover the meaning of Yehkuja and how it honors the goddess of fertility.', '{}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/news/News_01_2026.webp', NULL, NULL, NULL, 'public'),
	('c939d21a-f1a6-4bba-98f5-bca4c56a0c2d', 'From Opium to Arabica: The Coffee Revolution', 'akha-coffee-revolution', 'How our village transitioned to sustainable shade-grown coffee at 1,500m altitude.', 'Akha communities have pioneered a transition from opium cultivation to world-class coffee. Grown under a natural forest canopy...', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/news/News_01_2026.webp', 'coffee', '{sustainability,agriculture,history}', NULL, 4, true, false, '2026-02-10 09:00:54.263747+00', '2026-02-15 09:00:54.263747+00', '2026-02-15 09:00:54.263747+00', 'From Opium to Arabica: The Coffee Revolution', 'How our village transitioned to sustainable shade-grown coffee at 1,500m altitude.', '{}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/news/News_01_2026.webp', NULL, NULL, NULL, 'public'),
	('355ca9bb-b3ae-4500-b434-bafbdbeb9c0f', 'Why We Never Use Blenders', 'art-of-mortar-pestle', 'The secret to Akha flavor lies in the rhythm of the pestle. Learn why pounding ingredients releases oils that blades destroy.', '"Ciao a tutti e benvenuti nella mia cucina virtuale! Sono Cherry e sono felicissima di avervi qui con me. Oggi vi illustrerò tutte le fantastiche ricette che potrete cucinare con noi. Scopriremo insieme i segreti della cucina tailandese e Akha, e vi mostrerò cosa significa davvero cucinare con il cuore! Mettetevi comodi, perché vi farò venire l''acquolina in bocca.
INSERT INTO "public"."allergy_knowledge" ("allergy_key", "warning_text") VALUES
	('soy sauce', 'We substitute soy sauce with fish sauce or salt to maintain the savory balance.'),
	('fish sauce', 'Fish sauce can be substituted with soy sauce or salt.'),
	('eggs', 'Eggs can be omitted from most dishes. We can use extra tofu as a substitute.'),
	('fish', 'Fish sauce can be substituted with soy sauce or salt.'),
	('gluten', 'Traditional Soy Sauce contains wheat. We use Fish Sauce (Naturally GF) or certified Tamari as a swap.'),
	('peanuts', 'Peanuts are in Papaya Salad and Panang Curry. We use sunflower seeds as a crunchy substitute.'),
	('seafood', 'We can omit all seafood and use tofu or vegetables instead.'),
	('sesame', 'Sesame oil is rarely used. We can substitute with vegetable oil.'),
	('shellfish', 'Shrimp paste is in curries. We use the Salt-based adaptation for allergic guests.'),
	('soy', 'We substitute soy sauce with fish sauce or salt to maintain the savory balance.'),
	('tree nuts', 'We can substitute cashews with seeds or omit nuts completely.'),
	('others', 'Other specific allergies (e.g., dairy, celery, mustard, lupin, sulphites, molluscs, corn, nightshades, alliums, legumes, histamine, nickel, latex, and any other ingredient not listed above): Please specify your requirements to our Chef upon arrival. We are fully equipped to safely customize your menu and manage any food allergy at your personal cooking station. For allergies not listed in our main table, our kitchen has no inherent cross-contamination issues, and we will adapt recipes accordingly.');
