INSERT INTO "public"."class_sections" ("id", "section_key", "title", "subtitle", "description", "tag_badge", "ui_style", "assigned_classes", "display_order", "is_active", "created_at", "updated_at") VALUES
	('8eee20c1-f5a3-4e93-8cf2-c7b1bc6d3e18', 'shared_dietary', 'Alternative Solutions', 'Adapting to your needs', 'We can adapt all of our recipes to accommodate Vegan, Vegetarian, and Gluten-Free diets, as well as specific food allergies. Spiciness levels are also fully adjustable.', 'Allergies', 'accordion', '{morning_class,evening_class}', 20, true, '2026-03-23 08:41:18.909151+00', '2026-03-23 08:41:18.909151+00'),
	('033c34ee-6af1-473a-885e-79d764810e90', 'flow_step_1', 'Let’s get started: 2 Appetizers', 'Papaya Salad & Spring Rolls', 'Begin the session by hand-pounding a traditional Papaya Salad using a mortar and pestle, adjusting the chilies to your preference. Afterward, discover the technique for rolling crisp, perfect spring rolls.', 'Start', 'timeline', '{morning_class,evening_class}', 1, true, '2026-03-23 08:41:18.909151+00', '2026-03-23 08:41:18.909151+00'),
	('534aec09-f429-42a1-b2cc-128509ebcd51', 'morning_walkin', 'Walk-in / Don’t need pick-up', 'Meeting points options', 'Our facility is conveniently located a short 5-minute walk from the South Gate of Chiang Mai. You may join us directly at the kitchen at 8:50 am, or meet the group at Wat Pan Whaen temple at 9:00 am.', 'Location', 'alert_box', '{morning_class}', 30, true, '2026-03-23 08:41:18.909151+00', '2026-03-23 08:41:18.909151+00'),
	('87640ecf-1bc4-4a7f-a98a-f8ba488fdc66', 'evening_walkin', 'Walk-In / Don’t need pick-up', 'Meeting point at our kitchen', 'Our facility is conveniently located a short 5-minute walk from the South Gate of Chiang Mai. Please arrive directly at our kitchen by 5:00 pm for the evening session.', 'Location', 'alert_box', '{evening_class}', 30, true, '2026-03-23 08:41:18.909151+00', '2026-03-23 08:41:18.909151+00'),
	('7400f3f1-86ee-4470-b998-1cf501049d0a', 'shared_payments', 'Payments', 'Credit Card, PayPal or Cash', 'Payment can be made using most credit or debit cards. Your payment will be processed by PayPal on a secure website. A 3% fee will be charged on all credit and debit card transactions for on-site payments. Cash payment: We accept Thai Baht, US Dollars, or Euro.', 'Booking', 'accordion', '{morning_class,evening_class}', 10, true, '2026-03-23 08:41:18.909151+00', '2026-03-23 08:41:18.909151+00'),
	('7f5a23ae-129a-422b-95e3-1d4121c759f4', 'flow_step_2', 'Now let’s continue with 2 desserts', 'Mango Sticky Rice & Pumpkin in Coconut Milk', 'Learn the secrets of steaming perfect sticky rice for the classic Mango dessert, and discover how to make warm Pumpkin in Coconut Milk.', 'Sweet', 'timeline', '{morning_class,evening_class}', 2, true, '2026-03-29 09:26:06.501278+00', '2026-03-29 09:26:06.501278+00'),
	('eeeeb30c-ba18-400d-9f88-3eb144d60cdb', 'flow_step_3', '3 Akha dishes', 'A whole different world from Thai food', 'Master the traditional Akha trio: the signature Chili sauce (Sapi Thong), the Akha Mountain Fresh Salad, and the Akha Spirit Detox Soup.', 'Akha', 'timeline', '{morning_class,evening_class}', 3, true, '2026-03-29 09:26:06.501278+00', '2026-03-29 09:26:06.501278+00'),
	('ee0c3d66-ac4d-4f73-af8a-1ca2dd1d603a', 'flow_step_4', 'It’s Curry time!', 'Authentic paste from scratch', 'Learn how to make authentic curry paste from scratch with fresh ingredients. You can choose one of the four most popular Thai curries: Red, Green, Panang, or Massaman.', 'Spicy', 'timeline', '{morning_class,evening_class}', 4, true, '2026-03-29 09:26:06.501278+00', '2026-03-29 09:26:06.501278+00'),
	('9d49b934-bb53-4b36-984f-5ab1f55af887', 'flow_step_5', 'Let’s make some soup', 'Choose your favorite broth', 'Find out how Thai soup can taste so good! You can choose between: Chicken & Coconut Milk (Tom Kha), Hot and Sour Prawn Soup (Tom Yum Goong), or Clear Soup & Egg Tofu.', 'Soup', 'timeline', '{morning_class,evening_class}', 5, true, '2026-03-29 09:26:06.501278+00', '2026-03-29 09:26:06.501278+00'),
	('c0fa6153-eb57-4cde-9ddd-c547e93c07a2', 'flow_step_6', 'The grand finale, stir-fried dishes', 'Classic Thai street food', 'Master classic Thai street food dishes in a wok. You can choose the most famous Pad Thai or try one of the other delicious stir-fries: Chicken with Cashew Nuts, Holy Basil, or Sweet and Sour Vegetables.', 'Wok', 'timeline', '{morning_class,evening_class}', 6, true, '2026-03-29 09:26:06.501278+00', '2026-03-29 09:26:06.501278+00'),
	('d22c7c5d-e4e6-438a-8b85-c3d266759206', 'flow_step_7', 'Eat and Enjoy your Dishes', 'Taste your creations', 'We will be sitting and taking breaks to eat all the deliciously prepared food along the way! After the class, our driver will drop you off safely at your hotel.', 'Enjoy', 'timeline', '{morning_class,evening_class}', 7, true, '2026-03-29 09:26:06.501278+00', '2026-03-29 09:26:06.501278+00');
INSERT INTO "public"."content_categories" ("id", "domain", "title", "subtitle", "description", "content_body", "ui_quote", "image_url", "icon_name", "audio_story_url", "video_url", "author_name", "author_url", "author_bio", "cherry_context", "chef_secrets", "seo_keywords", "seo_priority", "translations", "is_active", "display_order", "created_at", "updated_at", "created_by", "updated_by", "title_highlight", "tab_label") VALUES
	('origins', 'history', 'The Journey from the', 'Migration patterns into Northern Thailand', 'Explore the historical migration patterns, the deep ancestral roots, and the highland mosaic of the resilient Akha people.', NULL, NULL, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/akha-history/01-historical_roots.webp', 'Map', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '{}', true, 1, '2026-04-03 14:55:25.56645+00', '2026-04-03 21:04:24.48907+00', NULL, NULL, 'Tibetan Plateau', 'Origins'),
	('dessert', 'recipe', 'Desserts', NULL, 'When you eat out in Thailand at a local restaurant, you''re likely to get a strange look if you ask to see a dessert menu after you''ve finished your meal. That''s because authentic Thai restaurants don''t serve what Westerners consider dessert. That sort of food is reserved for sweet shops and certain street vendors, and it isn''t often eaten after a meal. However, we should note that touristy restaurants serve dessert because they know their guests are probably looking for something like this after a meal. We call this khong wan (which literally means “sweet thing”), and it''s mostly reserved for free time. Sweet treats are the kind of food that a family with children might make in the afternoon as a snack. Similarly, you might order a sweet dessert at an event, a party or even a temple fair. It''s a one-off treat that you enjoy regardless of when you last ate. With that in mind, desserts are eaten throughout the day in Thailand. Grandma might wake up at 6 am to start making mango sticky rice because she knows her grandchildren are visiting at 9 am. When they arrive, they''ll eat mango sticky rice with her, regardless of whether they''ve had breakfast yet. In other words, it''s a fun food for free time. In this cookbook, we''re highlighting two desserts. The first is mango sticky rice, which is easily one of the most popular sweet treats in Thailand - with locals and tourists alike. You''ll find it sold by street vendors all over the country. The second dish we''re featuring is pumpkin in coconut milk. This is a very rich and sweet dessert that''s easy to make. In my opinion, it tastes even better with vanilla ice cream on top, although you can also enjoy it without. This dish is called buak fuk tong. “Buak” means white, which is the color the dish turns when prepared; “fuk” refers to any plant in the squash family; and “tong” means golden. So buak fuk tong is a golden squash (i.e. pumpkin) dish that turns white when prepared according to the recipe.', 'In Thailand, desserts are a fun free-time food [1]! Learn the secrets of steaming Mango Sticky Rice and making warm Pumpkin in Coconut Milk [1].', 'In Thailand, desserts are seen as a fun food to eat during your free time.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', 'IceCreamCone', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/song/GreenCurry.wav', NULL, NULL, NULL, NULL, 'Explain that desserts are often vegan and gluten-free by nature.', '{"Soak sticky rice for at least 4 hours","Salty coconut cream goes on top to contrast the sweet"}', NULL, 0, '{}', true, 3, '2026-04-03 15:06:59.039972+00', '2026-04-06 17:21:22.826101+00', NULL, NULL, NULL, NULL),
	('akha-zang', 'history', 'The Akha', 'Traditional code of conduct and identity', 'Discover the oral code of conduct, traditional indigo clothing, and the deep cultural identity that governs our daily life.', NULL, NULL, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/akha-history/01-akha_zang.webp', 'BookOpen', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '{}', true, 2, '2026-04-03 14:55:25.56645+00', '2026-04-03 21:02:44.488738+00', NULL, NULL, 'Way of Life', 'Akha Zang'),
	('spice', 'ingredient', 'Spices', NULL, 'When we think of Thai foods. We can smell and taste various spices and herbs that are in Thai dishes.
INSERT INTO "public"."cooking_classes" ("id", "title", "badge", "tags", "price", "currency", "unit", "theme_color", "duration_text", "tagline", "capacity_text", "image_url", "description", "highlights", "schedule_items", "inclusions", "is_active", "created_at") VALUES
	('morning_class', 'Morning Cooking Class', 'Most Popular', '{"Choose your dishes","Class run in English","1h Market Tour","Free CookBook + Extra Gift","Free cancellation - 48hrs notice"}', 1400, 'THB', 'per person', '#E31F33', '6h duration', 'Taste the unique Thai and Akha flavors during this 6-hour cooking class in Chiang Mai.', '12 people (16 if a private group)', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Akha01.jpg', 'Discover the culture and cuisine of the Akha, an indigenous Southeast-Asian hill tribe, with the help of our Akha teachers. An important part of the rich Thai culture is ingrained in all its delicious traditional dishes. Join a fun and informative tour that will take you on a local market trip where you will taste and collect all the ingredients for your cooking class! Choose a morning course and embark on a journey that will introduce you to the Akha people – a community that immigrated to Thailand in the 1900s – as well as their traditions and a combination of both Thai and Akha cuisine. In the cooking course, you’ll create 11 delicious dishes that you will get to eat after each cooking session.', '{"Thai Akha Kitchen will take you to the Local Market to see the real lifestyle of local people, where you can find all the same products, at different prices. We call this \"same same, but different\"!","At the Local Market, you will be treated as a local person, with no special treatment to gain profit for tourists here!","Thai markets are very different from Western markets, so get ready for some interesting experiences.","All of the products we will be using will come fresh from our farm and the local market."}', '[{"time": "8:15 am > 8:40 am (Zone Dependent)", "label": "Pick-Up Service Included", "description": "Exact time depends on your hotel location. Yellow Zone: 8:20 am. Green Zone (Old City): 8:30 am. Pink/Azure Zone: 8:40 am. Please be ready in the lobby."}, {"time": "9:00 am > 10:00 am", "label": "Market Visit Tour", "description": "We will take you to the local market, so you can experience the real lifestyle of the local people. See and taste all the different local products."}, {"time": "10:00 am > 2:30 pm", "label": "Class time", "description": "Once you arrive at the cooking school, you’ll begin to prepare a variety of dishes with the help of our Akha instructor."}, {"time": "2:30 pm > 3:00 pm", "label": "Drop-off time", "description": "Return to your hotel after eating your 11 delicious dishes."}]', '{"Pick-up from/to your place of stay","1h Market Tour","Individual cooking station","Full-color paper CookBook (40 pages)","Ingredient gift set for every Student","Complimentary samples of locally grown Akha Hill Tribe Coffee","Fresh water, and different teas","Free Wifi, charger plugs, and more are available"}', true, '2026-01-24 17:09:35.033708+00'),
	('evening_class', 'Evening Cooking Class', 'Great for Dinner', '{"Choose your own dishes","Class run in English","Hotel Pick-Up included","Free CookBook + Extra Gift","Free cancellation - 48hrs notice"}', 1300, 'THB', 'per person', '#6E004A', '5hrs duration', 'Taste the unique Thai and Akha flavors during this 5-hour cooking class in Chiang Mai.', '12 people (16 if a private group)', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-06.webp', 'Thai Akha Kitchen - Evening Cooking Class is perfect for the traveler who doesn’t have much time in Chiang Mai, but wants to learn a bit of cooking during their stay. An important part of the rich Thai culture is ingrained in all its delicious traditional dishes. Choose an evening course and embark on a journey that will introduce you to the Akha people – a community that immigrated to Thailand in the 1900s – as well as their traditions and a combination of both Thai and Akha cuisine. In the cooking course, you’ll create 11 delicious dishes that you will get to eat after each cooking session.', '{"Fits around a busy day schedule","First home-cooked Thai dinner in Thailand.","No need to worry or plan where or what to eat for dinner, just come and cook!","It’s cooler in the evening, actually a much better time to be cooking."}', '[{"time": "4:15 pm > 4:40 pm (Zone Dependent)", "label": "Pick-Up service included", "description": "Exact time depends on your hotel location. Yellow Zone: 4:20 pm. Green Zone (Old City): 4:30 pm. Pink/Azure Zone: 4:40 pm. Please be ready in the lobby."}, {"time": "5:00 pm > 9:00 pm", "label": "Class time", "description": "Create 11 delicious dishes that you will get to eat after each cooking session."}, {"time": "9:00 pm > 9:30 pm", "label": "Drop off time", "description": "Return to your hotel."}]', '{"Pick-up from/to your place of stay","Individual cooking station","Full-color paper Cookbook (40 pages)","An ingredient gift set for every Student","Complimentary samples of locally grown Akha Hill Tribe Coffee","Fresh water, and different teas","Free Wifi, charger plugs, and more are available"}', true, '2026-01-24 17:09:35.033708+00');
INSERT INTO "public"."culture_sections" ("id", "display_order", "title", "subtitle", "content", "featured", "primary_image", "quote", "slug", "gallery_images", "seo_title", "seo_description", "is_published", "category", "audio_asset_id", "published_at", "updated_at", "author_name", "seo_keywords", "seo_robots", "og_image", "category_id", "json_ld") VALUES
	('traditional_dress', 3, 'The Language of Beads, Silver, and Indigo', 'A deep dive into traditional Akha dress, headgear, and the symbolism of embroidery.', 'Traditional clothing is not just decoration. It is a way to show identity, family history, and beliefs without using words. Every bead, coin, stitch, and piece of silver has meaning and is passed down from one generation to the next.
INSERT INTO "public"."dietary_profiles" ("id", "name", "icon", "introduction", "experience", "slug", "icon_name", "display_order", "type", "image_url") VALUES
	('diet_regular', 'Regular Diet', '🍽️', 'A regular diet reflects authentic Thai habits, fully embracing the traditional flavors and vibrant ingredients found in our local markets.', 'Experience the standard authentic preparation, perfectly balancing the traditional ingredients that make Thai and Akha cuisine world-famous.', 'diet_regular', 'Utensils', 1, 'lifestyle', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp'),
	('diet_vegan', 'Vegan Diet', '🌱', 'Chiang Mai is a true vegan paradise. We embrace this by offering entirely plant-based culinary experiences that celebrate fresh produce.', 'Every dish is naturally tailored with premium mushroom stock and plant-based umami to deliver a 100% authentic Thai flavor.', 'diet_vegan', 'Leaf', 2, 'lifestyle', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-03.webp'),
	('diet_vegetarian', 'Vegetarian Diet', '🥬', 'Vegetarians deeply enjoy all the authentic tastes of Akha cooking through vibrant, farm-fresh vegetables that honor our rich culinary heritage.', 'Your menu is beautifully crafted with fresh local tofu and vegetables, perfectly balancing the rich and traditional spices.', 'diet_vegetarian', 'Carrot', 3, 'lifestyle', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg'),
	('diet_pescatarian', 'Pescatarian Diet', '🐟', 'Pescatarians follow a fresh vegetarian diet plus premium seafood, enjoying the perfect harmony of coastal ingredients and authentic Thai spices.', 'We enhance your culinary journey with premium local seafood and authentic ingredients for a perfectly balanced coastal taste.', 'diet_pescatarian', 'Fish', 4, 'lifestyle', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-02.webp'),
	('diet_meat_lover', 'Meat-Lover', '🍗', 'Designed for those who want a protein-packed, rich, and meat-forward culinary experience that highlights the robust, savory flavors of Thailand.', 'Your culinary experience is elevated with premium cuts of local meats, maximizing the savory richness of traditional recipes.', 'meat-lover', 'drumstick', 5, 'lifestyle', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-02.webp'),
	('diet_halal', 'Halal Friendly', '☪️', 'This diet strictly adheres to Islamic dietary laws prohibiting pork, blood, and alcohol. We ensure purity and respect the sanctity of life.', 'Your dishes are thoughtfully prepared with strictly compliant ingredients, ensuring absolute purity and traditional Akha richness.', 'diet_halal', 'ShieldCheck', 10, 'religious', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/halal-friendly.webp'),
	('diet_kosher', 'Kosher Friendly', '✡️', 'Based on Kashrut laws of purity. We focus on the exclusion of shellfish (shrimp/crab) and the strict separation of meat and dairy.', 'We carefully select pure, compliant ingredients to deliver a deeply authentic flavor while strictly honoring your dietary laws.', 'diet_kosher', 'Star', 11, 'religious', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/kosher-friendly.webp'),
	('diet_rastafari', 'Rastafari (Ital)', '🦁', 'Follows the principle of "I-tal" (Vital): natural, clean eating to increase life energy. No pork, shellfish, or processed additives.', 'Your culinary experience embraces the I-tal philosophy, utilizing pure, naturally sourced ingredients to deliver vibrant and clean flavors.', 'diet_rastafari', 'Flame', 12, 'religious', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/ital-clean.webp'),
	('diet_jainism', 'Jain Friendly', '🕉️', 'Rooted in Ahimsa (non-violence). Strictly excludes meat, eggs, and ROOT VEGETABLES (garlic, onion, potatoes, carrots) to protect soil life.', 'Your recipes are harmoniously crafted using natural, non-root vegetables while fully preserving the vibrant essence of Thai cooking.', 'diet_jainism', 'Leaf', 13, 'religious', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/jain-friendly.webp'),
	('diet_hinduism', 'Hindu Friendly', '🕉️', 'Respects the sacredness of life. Beef is strictly prohibited. Many followers avoid foods that excite the senses (poultry/eggs).', 'Your menu is deeply respectful of your traditions, utilizing rich, pure ingredients to celebrate the authentic local taste.', 'diet_hinduism', 'Sun', 14, 'religious', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/hindu-friendly.webp');
