INSERT INTO "public"."ethnic_groups" ("id", "section_id", "name", "origins", "cultural_depth", "quote", "distinction") VALUES
	(1, 'hill_tribes_overview', 'Karen (Pwa Ka Nyaw)', 'Tibeto-Burman / Myanmar', 'As the most populous group in Thailand, the Karen are esteemed for their ecological stewardship...', 'If the forest dies, the Karen cannot live; if the water dries, the Karen cannot breathe.', 'Renowned for their harmonious relationship with elephants and sustainable terrace rice cultivation.'),
	(2, 'hill_tribes_overview', 'Hmong (Miao)', 'Hmong-Mien / Southern China', 'Celebrated for their entrepreneurial spirit and textile arts. They are masters of wax-resist indigo batik...', 'A man without a clan is like a bird without a wing; a woman without a needle is like a field without rain.', 'Famous for the ''hundred-pleat'' skirts and heavy, ornate silver neck rings.'),
	(4, 'hill_tribes_overview', 'Mien (Yao)', 'Hmong-Mien / China', 'Unique among hill tribes for adopting Chinese characters and Taoist practices...', 'A needle is our pen, and thread is our ink, writing the history of our ancestors on the cloth of today.', 'The only group to possess ancient hand-written ritual books and a complex pantheon of Taoist deities.'),
	(5, 'hill_tribes_overview', 'Lisu (Lisaw)', 'Tibeto-Burman / Tibetan Plateau', 'Known as the ''Rainbow People'' for neon-bright multi-layered tunics...', 'We wear the colors of the sunrise so the spirits may always find us happy.', 'Distinguished by highly competitive ''merit-feasts'' and thousands of tiny silver buttons on festive garments.'),
	(3, 'hill_tribes_overview', 'Lahu (Mussur)', 'Tibeto-Burman / Yunnan', 'Historically ''The Great Hunters,'' their spiritual life centers on ''G’ui-sha'' (a supreme deity)...', 'The forest is our mother, the crossbow is our father, and the community is our heart.', 'Renowned for their mastery of the ''Khene'' (bamboo organ) and egalitarian social structure.');
INSERT INTO "public"."media_assets" ("id", "file_name", "folder_path", "image_url", "alt_text", "title", "caption", "mime_type", "size_kb", "width", "height", "uploaded_by", "created_at", "updated_at", "asset_id", "copyright", "tags", "is_ai_generated", "ai_tool") VALUES
	('0869e1fa-364d-40fa-b08c-af332b830eec', 'learn-about-akha-people.webp', 'why_choose_us', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Swing-01.webp', 'Students learning authentic Akha cooking techniques in a traditional Thai outdoor and indoor kitchen setting.', 'Learn About Akha People', 'The first school in Thailand teaching authentic Akha cooking in both traditional indoor and outdoor settings.', 'image/webp', 450, 1920, 1080, NULL, '2026-03-20 11:23:28.650662+00', '2026-03-20 11:23:28.650662+00', 'class-01', '© 2026 Thai Akha Kitchen', '{}', true, 'Google Flow'),
	('867098b7-bf9c-4b17-b73e-de2e08d416a4', 'detailed-explanations.webp', 'why_choose_us', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-02.webp', 'A professional Thai-Akha Chef providing step-by-step instructions on traditional tribal cooking techniques.', 'Detailed Explanations', 'Master traditional techniques under the guidance of an expert Akha Chef who pays attention to every detail.', 'image/webp', 310, 1200, 800, NULL, '2026-03-20 11:23:28.650662+00', '2026-03-20 11:23:28.650662+00', 'class-05', '© 2026 Thai Akha Kitchen', '{}', true, 'Google Flow'),
