	('a48e969a-6ff6-4d61-8237-d7b831e5ff66', 'Our Highland', 'Discover the origins of the Akha people, the meaning behind our headdress, and our life in the mountains of Chiang Rai.', 'History', '/history', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Akha01.jpg', 'Landmark', 'cherry', 40, true, '2026-03-17 04:33:47.853304+00', '2026-03-17 04:33:47.853304+00'),
	('6fa968ac-8f64-4200-b5fc-83b4fce10121', 'Classic Website', 'Looking for the traditional experience? Visit our historical website for full photo galleries and legacy content.', NULL, 'https://www.thaiakhakitchen.com', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Akha01.jpg', 'language', 'secondary', 20, true, '2026-03-31 15:19:34.155519+00', '2026-03-31 15:19:34.155519+00'),
	('e894a9f9-9e32-4421-91c9-af67dda37a14', 'Akha Culture & History', 'How well do you know the Hill Tribes? Answer correct questions to earn your ''Guardian'' badge.', 'Akha Culture Quiz', '/quiz', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Akha01.jpg', 'Trophy', 'cherry', 70, true, '2026-03-17 04:33:47.853304+00', '2026-03-17 04:33:47.853304+00'),
	('196c40ec-b268-4844-a4d8-0deafa7026e3', 'Akha Culture', 'Sawasdee kha! Explore our cooking classes, discover authentic recipes, and dive into the rich Akha culture.', 'Home', '/home', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp', 'Home', 'cherry', 100, true, '2026-03-17 04:33:47.853304+00', '2026-03-17 04:33:47.853304+00'),
