INSERT INTO "public"."meeting_points" ("id", "name", "description", "latitude", "longitude", "google_maps_link", "active", "image_url", "icon_url", "morning_pickup_time", "morning_pickup_end", "evening_pickup_time", "evening_pickup_end") VALUES
	('mp_cen_airport', 'Central Airport Plaza', 'Wait in front of the entrance to Central Plaza Gate.', 18.7694222, 98.976272, 'https://www.google.co.th/maps/@18.7694222,98.976272,3a,90y,231.9h,84.92t/data=!3m7!1e1!3m5!1s00FbAapnfqudi5AOyk0CDQ!2e0', true, NULL, NULL, '08:20:00', '08:30:00', '16:20:00', '16:30:00'),
	('mp_train_station', 'Chiang Mai Train Station', 'Wait outside of Coffee and Drink Mini Mart next to the Clock''s tower.', 18.7839867, 99.0168722, 'https://www.google.com/maps/@18.7839867,99.0168722,3a,75.3y,332.45h,110.59t/data=!3m8!1e1!3m6!1sCIHM0ogKEICAgIDEn6SobA!2e10', true, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp', 'https://cdn-icons-png.flaticon.com/512/1950/1950630.png', '08:20:00', '08:30:00', '16:20:00', '16:30:00'),
	('mp_central_festival', 'Central Festival', 'Wait on the main street in front of the BUS Stop Sign.', 18.8062631, 99.0171528, 'https://www.google.co.th/maps/@18.8062631,99.0171528,3a,75y,39.62h,72.15t/data=!3m7!1e1!3m5!1shglJ6i-oXl7ztlJAudjfrQ!2e0', true, NULL, NULL, '08:15:00', '08:20:00', '16:15:00', '16:20:00'),
	('mp_maya', 'MAYA Shopping Center', 'Wait on the main street in front of the entrance to ONE Nimman.', 18.8000865, 98.9674033, 'https://www.google.com/maps/@18.8000865,98.9674033,3a,75y,141.36h,99.92t/data=!3m7!1e1!3m5!1sSZ0SVcYYO2Brr7rY8izFYg!2e0', true, NULL, NULL, '08:20:00', '08:30:00', '16:20:00', '16:30:00'),
	('mp_thaphae', 'Mac Donald - Tha Phae Gate', 'Wait on the main street in front of the entrance to Mac Donald.', 18.7875434, 98.9937728, 'https://www.google.co.th/maps/@18.7875434,98.9937728,3a,75y,126.59h,87.67t/data=!3m7!1e1!3m5!1spSZQWj4hGaCU7uNUcvzTlg!2e0', true, NULL, NULL, '08:30:00', '09:00:00', '16:30:00', '17:00:00'),
	('mp_north_gate_b2', 'North Gate - B2 Hotel', 'Wait on the main street in front of B2 Hotel.', 18.7957734, 98.9851003, 'https://www.google.co.th/maps/@18.7957734,98.9851003,3a,75y,320.99h,85.43t/data=!3m7!1e1!3m5!1sd4qXOIRZrd-jvM7zXZBOYA!2e0', true, NULL, NULL, '08:30:00', '09:00:00', '16:30:00', '17:00:00'),
	('mp_wat_pan_whaen', 'Wat Pan Whean (Temple)', 'Morning market meeting point. Walk inside near the big white Pagoda. Look for crews in Thai Akha Kitchen aprons.', 18.7829254, 98.9857705, 'https://goo.gl/maps/brDduAydRvksy4ip7', true, NULL, NULL, '08:50:00', '09:00:00', NULL, NULL),
	('mp_school', 'Thai Akha Kitchen - Chiang Mai', 'Go directly to school. Please arrive by 8:50 am for morning class or 4:50 pm for evening class.', 18.7761982, 98.9923569, 'https://maps.app.goo.gl/mPryxjme4AVfDY7n7', true, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Akha01.jpg', 'https://cdn-icons-png.flaticon.com/512/1046/1046857.png', '08:50:00', NULL, '16:50:00', NULL),
	('mp_airport_gate1', 'Chiang Mai Airport - International', 'International flight: Wait outside exit Gate 8. Note: Free pickup not included. We can help arrange a Grab taxi (~150-200 THB) paid to the driver.', 18.77043, 98.968484, 'https://www.google.com/maps/place/Chiang+Mai+International+Airport/@18.7676473,98.9684635,3a,75y,310.91h,91.54t/data=!3m7!1e1!3m5!1sEDuYqHFJW0hvqign-5hfMQ!2e0!6shttps:%2F%2Fstreetviewpixels-pa.googleapis.com%2Fv1%2Fthumbnail%3Fcb_client%3Dmaps_sv.tactile%26w%3D900%26h%3D600%26pitch%3D-1.5431202901348087%26panoid%3DEDuYqHFJW0hvqign-5hfMQ%26yaw%3D310.9084662581357!7i16384!8i8192!4m7!3m6!1s0x30da3088e698f189:0xa02474e3fd934597!8m2!3d18.7692428!4d98.9681891!10e5!16zL20vMDFuZmdu?entry=ttu&g_ep=EgoyMDI2MDIxNi4wIKXMDSoASAFQAw%3D%3D', true, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-02.webp', 'https://cdn-icons-png.flaticon.com/512/7893/7893910.png', '08:20:00', '08:30:00', '16:20:00', '16:30:00'),
	('mp_airport_gate2', 'Chiang Mai Airport - Domestic', 'Domestic flight: Wait outside exit Gate 2. Note: Free pickup not included. We can help arrange a Grab taxi (~150-200 THB) paid to the driver.', 18.767942, 98.968476, 'https://www.google.com/maps/place/Chiang+Mai+International+Airport/@18.7700047,98.9684771,3a,75y,302.64h,78.44t/data=!3m7!1e1!3m5!1sod5F8S2_AiXYxBvwcury4g!2e0!6shttps:%2F%2Fstreetviewpixels-pa.googleapis.com%2Fv1%2Fthumbnail%3Fcb_client%3Dmaps_sv.tactile%26w%3D900%26h%3D600%26pitch%3D11.555018017299034%26panoid%3Dod5F8S2_AiXYxBvwcury4g%26yaw%3D302.6444253542367!7i16384!8i8192!4m7!3m6!1s0x30da3088e698f189:0xa02474e3fd934597!8m2!3d18.7692428!4d98.9681891!10e5!16zL20vMDFuZmdu?entry=ttu&g_ep=EgoyMDI2MDIxNi4wIKXMDSoASAFQAw%3D%3D', true, NULL, NULL, '08:20:00', '08:30:00', '16:20:00', '16:30:00');
INSERT INTO "public"."recipes" ("id", "name", "thai_name", "description", "is_vegan", "is_vegetarian", "category", "has_peanuts", "has_shellfish", "has_gluten", "has_soy", "image", "spiciness", "color_theme", "health_benefits", "is_signature", "is_fixed_dish", "created_at", "updated_at", "dietary_variants", "gallery_images", "slug", "seo_title", "seo_description", "seo_keywords", "seo_robots", "og_image", "is_published", "published_at", "author_name", "audio_asset_id", "subtitle", "excerpt", "json_ld") VALUES
	('soup_02', 'Tom Yum (Hot & Sour)', 'Tom Yum Goong', 'The world-famous spicy and sour soup with fresh lime and herbs.', true, true, 'soup', false, true, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp', 3, '#FF5722', 'Packed with lemongrass and chilies, it acts as a powerful natural remedy to clear respiratory paths.', false, false, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'tom-yum-hot-&-sour', 'Tom Yum (Hot & Sour)', 'Spice up your culinary skills with authentic Tom Yum Goong. Cook this iconic hot and sour Thai soup from scratch during our Chiang Mai cooking class.', '{"tom yum goong","hot and sour soup","spicy thai soup","chiang mai cooking class"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'soup-02', 'Hot & Sour Prawn Soup', 'Thailand''s iconic hot and sour prawn soup, delivering a fiery kick of chili and lime.', '{"name": "Tom Yum (Hot & Sour)", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "tom yum goong, hot and sour soup, spicy thai soup, chiang mai cooking class", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Spice up your culinary skills with authentic Tom Yum Goong. Cook this iconic hot and sour Thai soup from scratch during our Chiang Mai cooking class.", "recipeCuisine": "Thai", "recipeCategory": "soup"}'),
	('dess_02', 'Pumpkin in Coconut Milk', 'บวดฟักทอง', 'Traditional warm dessert featuring local pumpkin in a rich, sweet coconut cream.', true, true, 'dessert', false, false, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', 1, '#FB8C00', 'Thai pumpkin is highly rich in beta-carotene, which is essential for eye health and immunity.', false, true, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'pumpkin-in-coconut-milk', 'Pumpkin in Coconut Milk', 'Experience the comforting taste of Pumpkin in Coconut Milk. Master this warm, traditional Thai dessert using fresh local ingredients at Thai Akha Kitchen.', '{"pumpkin in coconut milk","buak fuk tong","traditional thai sweets","authentic thai dessert"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'dessert-02', 'Warm & Comforting Thai Sweet', 'A warm, comforting traditional sweet featuring local Thai pumpkin simmered in rich coconut cream.', '{"name": "Pumpkin in Coconut Milk", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "pumpkin in coconut milk, buak fuk tong, traditional thai sweets, authentic thai dessert", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Experience the comforting taste of Pumpkin in Coconut Milk. Master this warm, traditional Thai dessert using fresh local ingredients at Thai Akha Kitchen.", "recipeCuisine": "Thai", "recipeCategory": "dessert"}'),
	('app_02', 'Fried Spring Rolls', 'ปอเปี๊ยะทอด', 'Crispy hand-rolled pastries with a savory vegetable and glass noodle filling.', true, true, 'appetizer', false, false, true, true, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-03.webp', 1, '#222420', 'Provides a quick source of energy and essential fiber from the fresh vegetable filling.', false, true, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'fried-spring-rolls', 'Fried Spring Rolls', 'Master the art of crispy Fried Spring Rolls. Join our Chiang Mai cooking class to prepare this classic Thai appetizer with a savory vegetable filling.', '{"fried spring rolls","thai spring roll recipe","chiang mai cooking class","vegetable spring rolls"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-03.webp', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'appetizer-02', 'Golden & Crispy Starters', 'Crispy golden spring rolls packed with savory vegetables and glass noodles, perfect as a light starter.', '{"name": "Fried Spring Rolls", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-03.webp", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "fried spring rolls, thai spring roll recipe, chiang mai cooking class, vegetable spring rolls", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Master the art of crispy Fried Spring Rolls. Join our Chiang Mai cooking class to prepare this classic Thai appetizer with a savory vegetable filling.", "recipeCuisine": "Thai", "recipeCategory": "appetizer"}'),
	('soup_01', 'Tom Kha (Coconut Milk)', 'ต้มข่าไก่', 'Fragrant coconut milk soup infused with galangal and lemongrass.', true, true, 'soup', false, false, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', 1, '#ECEFF1', 'Galangal and coconut milk work together to soothe the stomach and boost the immune system.', false, false, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'tom-kha-coconut-milk', 'Tom Kha (Coconut Milk)', 'Learn how to make Tom Kha Gai, Thailand''s famous coconut milk soup. Discover the secret of using fresh galangal and lemongrass at Thai Akha Kitchen.', '{"tom kha gai","thai coconut soup","authentic thai recipe","chiang mai cooking school"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'soup-01', 'Coconut & Galangal Broth', 'A fragrant and creamy coconut milk broth infused with fresh galangal, lemongrass, and herbs.', '{"name": "Tom Kha (Coconut Milk)", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "tom kha gai, thai coconut soup, authentic thai recipe, chiang mai cooking school", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Learn how to make Tom Kha Gai, Thailand''s famous coconut milk soup. Discover the secret of using fresh galangal and lemongrass at Thai Akha Kitchen.", "recipeCuisine": "Thai", "recipeCategory": "soup"}'),
	('soup_03', 'Clear Soup (Egg Tofu)', 'แกงจืด', 'A light, healthy broth with silken tofu and garden vegetables.', true, true, 'soup', false, false, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Akha01.jpg', 1, '#B0BEC5', 'A hydrating, low-calorie broth that provides light and easily digestible protein from egg tofu.', false, false, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'clear-soup-egg-tofu', 'Clear Soup (Egg Tofu)', 'Prepare a light, healthy Clear Soup with egg tofu. A comforting, mild Thai recipe perfect for balancing spicy flavors, taught at Thai Akha Kitchen.', '{"thai clear soup","gaeng jued","healthy thai recipes","tofu soup"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Akha01.jpg', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'soup-03', 'Light & Healthy Broth', 'A comforting and mild clear broth made with soft egg tofu and fresh garden vegetables.', '{"name": "Clear Soup (Egg Tofu)", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Akha01.jpg", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "thai clear soup, gaeng jued, healthy thai recipes, tofu soup", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Prepare a light, healthy Clear Soup with egg tofu. A comforting, mild Thai recipe perfect for balancing spicy flavors, taught at Thai Akha Kitchen.", "recipeCuisine": "Thai", "recipeCategory": "soup"}'),
	('stirfry_01', 'Pad Thai', 'ผัดไทย', 'Classic stir-fried rice noodles with our signature tamarind sauce.', true, true, 'stirfry', true, true, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-03.webp', 1, '#FFA000', 'Tamarind sauce naturally aids digestion while providing essential antioxidants to help protect the heart.', false, false, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'pad-thai', 'Pad Thai', 'Uncover the secrets of the perfect Pad Thai. Join our traditional cooking class in Chiang Mai to master Thailand''s signature stir-fried rice noodles.', '{"pad thai recipe","authentic pad thai","thai stir fry noodles","chiang mai cooking class"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-03.webp', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'stirfry-01', 'Classic Tamarind Rice Noodles', 'The ultimate Thai street food classic featuring stir-fried rice noodles in our homemade tamarind sauce.', '{"name": "Pad Thai", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-03.webp", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "pad thai recipe, authentic pad thai, thai stir fry noodles, chiang mai cooking class", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Uncover the secrets of the perfect Pad Thai. Join our traditional cooking class in Chiang Mai to master Thailand''s signature stir-fried rice noodles.", "recipeCuisine": "Thai", "recipeCategory": "stirfry"}'),
	('curry_02', 'Thai Green Curry', 'Gaeng Kheow Waan', 'Enjoy the fresh flavour of the green pepper and coriander stems used to make the green curry paste in this recipe. The coconut milk sweetens the curry and turns it into a rich, green colour. That’s why it’s called “gaeng kheow waan” (or “sweet green curry”). It was originally invented by Thai cooks who modified red curry by switching red peppers for green peppers and using coconut milk instead of water.', true, true, 'curry', false, true, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp', 3, '#388E3C', 'Fresh green chilies and coriander stems deliver a massive boost of vitamins and antioxidants.', false, false, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{"diet_halal": {"name": "Green Curry Chicken", "description": "Cooked with strict purity standards. We use Halal-compliant chicken or tofu, ensuring the fresh green paste is free from any non-compliant additives or alcohol.", "healthBenefits": "Fresh, clean ingredients that support a healthy immune system.", "keyIngredients": ["Green Curry Paste", "Coconut Milk", "Halal Chicken", "Thai Eggplant", "Sweet Basil"]}, "diet_vegan": {"name": "Green Garden Curry", "description": "The freshest of all curries. We pound fresh green chilies with lemongrass and galangal. Soy sauce replaces fish sauce to create a bright, vibrant plant-based dish that sings with the flavor of Thai Basil.", "healthBenefits": "Green chilies are packed with Vitamin C and the herbs aid detox.", "keyIngredients": ["Green Curry Paste (No Shrimp)", "Coconut Milk", "Firm Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_kosher": {"name": "Green Curry Tofu", "description": "We adapt this herbal masterpiece by removing the shrimp paste and using sea salt. Tofu is used as the protein to ensure pareve status regarding the coconut milk base.", "healthBenefits": "A kosher-compliant explosion of fresh herbal flavors.", "keyIngredients": ["Green Curry Paste (Salt Base)", "Coconut Milk", "Firm Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_jainism": {"name": "Green Curry Jai", "description": "A custom preparation omitting green onions, garlic, and coriander roots. We use the green leaves of the herbs and chilies to achieve the signature color without harming the plant roots.", "healthBenefits": "Promotes non-violence and easy digestion.", "keyIngredients": ["Green Chili (Flesh Only)", "Coconut Milk", "Firm Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_hinduism": {"name": "Green Curry Tofu", "description": "A pure vegetarian delight. We skip all meat and eggs, focusing on the lush, herbal flavors of the green paste, enriched with coconut cream and firm tofu.", "healthBenefits": "Cooling coconut balances the heating green chilies.", "keyIngredients": ["Green Curry Paste", "Coconut Milk", "Firm Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_meatlover": {"name": "Green Curry Chicken", "description": "The most popular version in Chiang Mai. Tender chicken breast balances the sharp, herbal heat of the fresh green chili paste. A perfect harmony of spicy and creamy.", "healthBenefits": "Chicken provides B-vitamins while Kaffir Lime leaves support oral health.", "keyIngredients": ["Green Curry Paste", "Coconut Milk", "Chicken Breast", "Thai Eggplant", "Sweet Basil"]}, "diet_rastafari": {"name": "Ital Green Curry", "description": "Green is the color of life. We use fresh, living herbs pounded by hand, natural sea salt, and coconut milk to create a dish that vibrates with vital energy.", "healthBenefits": "Chlorophyll-rich ingredients to alkalize the body.", "keyIngredients": ["Green Curry Paste (Pure)", "Coconut Milk", "Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_vegetarian": {"name": "Green Garden Curry", "description": "A vibrant green curry focusing on the chlorophyll-rich paste made from fresh green bird''s eye chilies. Served with tofu and eggplants, it offers a creamy yet spicy vegetarian feast.", "healthBenefits": "High in antioxidants and essential vitamins from fresh green herbs.", "keyIngredients": ["Green Curry Paste (No Shrimp)", "Coconut Milk", "Firm Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_pescatarian": {"name": "Green Curry Prawns", "description": "The sweetness of the coconut milk and the heat of green chilies pair perfectly with fresh prawns. The shrimp paste in the base adds a profound oceanic depth.", "healthBenefits": "Lean protein with metabolism-boosting green chilies.", "keyIngredients": ["Green Curry Paste", "Coconut Milk", "Fresh Prawns", "Thai Eggplant", "Sweet Basil"]}}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'thai-green-curry', 'Thai Green Curry', 'Master the authentic Thai Green Curry. Use fresh green chilies and aromatic herbs to create this vibrant, spicy classic in our Chiang Mai cooking class.', '{"thai green curry","gaeng kheow waan","green curry paste","chiang mai cooking school"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'curry-02', 'Vibrant & Aromatic Classic', 'A vibrant, herbaceous, and spicy classic featuring fresh green chilies, sweet basil, and rich coconut milk.', '{"name": "Thai Green Curry", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "thai green curry, gaeng kheow waan, green curry paste, chiang mai cooking school", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Master the authentic Thai Green Curry. Use fresh green chilies and aromatic herbs to create this vibrant, spicy classic in our Chiang Mai cooking class.", "recipeCuisine": "Thai", "recipeCategory": "curry"}'),
	('curry_03', 'Thai Panang Curry', 'Gaeng Panang', 'This curry has Indian and Malay influence and is made by mixing Indian curry powder (Garam Masala) with galangal, lemongrass and kaffir lime. Panang curry is perfect for meat lovers, as there are no vegetables in it. Chicken is the most popular meat used in Panang in Thailand, but some southern parts of Thailand use beef instead.', true, true, 'curry', true, true, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp', 2, '#E64A19', 'Roasted peanuts and rich coconut cream provide healthy fats and sustained, long-lasting energy.', false, false, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{"diet_halal": {"name": "Panang Chicken", "description": "Prepared using Halal-compliant chicken. The sauce is naturally alcohol-free, relying on the reduction of coconut cream and peanuts for its legendary thickness.", "healthBenefits": "Sustained energy release from healthy fats and proteins.", "keyIngredients": ["Panang Paste", "Coconut Cream", "Halal Chicken", "Roasted Peanuts", "Kaffir Lime"]}, "diet_vegan": {"name": "Panang Tofu", "description": "A rich, nutty curry with a thicker consistency. We roast peanuts and blend them with red curry paste, replacing shrimp paste with salt for a savory vegan masterpiece.", "healthBenefits": "Peanuts provide resveratrol and healthy monounsaturated fats.", "keyIngredients": ["Panang Paste (No Shrimp)", "Coconut Cream", "Firm Tofu", "Roasted Peanuts", "Kaffir Lime"]}, "diet_kosher": {"name": "Panang Tofu", "description": "A nutty delight adapted for Kashrut. We remove the shrimp paste and use sea salt. Tofu replaces meat to ensure strict separation from the coconut milk base.", "healthBenefits": "A kosher comfort food rich in essential minerals.", "keyIngredients": ["Panang Paste (Salt Base)", "Coconut Cream", "Firm Tofu", "Roasted Peanuts", "Kaffir Lime"]}, "diet_jainism": {"name": "Panang Jai", "description": "We make a special paste omitting garlic and shallots, relying on the roasted peanuts, cumin, and coriander seeds to build the rich body of the curry.", "healthBenefits": "Nourishing and grounding without root vegetables.", "keyIngredients": ["Panang Spices", "Coconut Cream", "Firm Tofu", "Roasted Peanuts", "Kaffir Lime"]}, "diet_hinduism": {"name": "Panang Tofu", "description": "A hearty, thick curry that satisfies without beef. We use tofu or paneer-style curd to soak up the luxurious peanut and coconut sauce.", "healthBenefits": "Excellent source of plant-based protein and fiber.", "keyIngredients": ["Panang Paste", "Coconut Cream", "Firm Tofu", "Roasted Peanuts", "Kaffir Lime"]}, "diet_meatlover": {"name": "Panang Chicken", "description": "A meat-lover''s favorite. Less watery than other curries, the thick peanut and coconut sauce coats the chicken pieces, infused with the citrus aroma of Kaffir Lime leaves.", "healthBenefits": "Protein-dense with the mood-boosting properties of peanuts.", "keyIngredients": ["Panang Paste", "Coconut Cream", "Chicken Breast", "Roasted Peanuts", "Kaffir Lime"]}, "diet_rastafari": {"name": "Ital Panang", "description": "A celebration of the earth''s nuts and fruits. Roasted peanuts and coconut cream provide natural richness without processed additives or animal products.", "healthBenefits": "High in natural fats for vitality and stamina.", "keyIngredients": ["Panang Paste (Pure)", "Coconut Cream", "Tofu", "Roasted Peanuts", "Kaffir Lime"]}, "diet_vegetarian": {"name": "Panang Tofu", "description": "Thick, salty, and sweet. The vegetarian version relies on the deep flavor of roasted peanuts and coconut cream, served with tofu instead of meat.", "healthBenefits": "High energy dish rich in plant-based proteins.", "keyIngredients": ["Panang Paste (No Shrimp)", "Coconut Cream", "Firm Tofu", "Roasted Peanuts", "Kaffir Lime"]}, "diet_pescatarian": {"name": "Panang Prawns", "description": "The rich, peanut-based sauce clings perfectly to fresh prawns. The addition of shrimp paste makes this one of the most savory curries in Thai cuisine.", "healthBenefits": "Good source of selenium and heart-healthy fats from peanuts.", "keyIngredients": ["Panang Paste", "Coconut Cream", "Fresh Prawns", "Roasted Peanuts", "Kaffir Lime"]}}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'thai-panang-curry', 'Thai Panang Curry', 'Discover the rich, nutty flavors of Panang Curry. Learn how to hand-pound traditional spices and roasted peanuts in our authentic Thai cooking class.', '{"panang curry recipe","peanut curry paste","authentic panang","thai cooking class"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'curry-03', 'Sweet, Salty & Nutty Paste', 'A thick, sweet, and salty curry paste enriched with roasted peanuts and fragrant kaffir lime leaves.', '{"name": "Thai Panang Curry", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-01.webp", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "panang curry recipe, peanut curry paste, authentic panang, thai cooking class", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Discover the rich, nutty flavors of Panang Curry. Learn how to hand-pound traditional spices and roasted peanuts in our authentic Thai cooking class.", "recipeCuisine": "Thai", "recipeCategory": "curry"}'),
	('curry_04', 'Thai Massaman Curry', 'Gaeng Massaman', 'Massaman Curry is originally from the southern region of Thailand and ultimately comes from Malay cuisine. It’s cooked with potatoes, Thai Red Curry Paste, cinnamon sticks, cardamom pods, bay leaves and star anise seeds. We also add ground peanuts to give it a creamier texture.', true, true, 'curry', true, true, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', 1, '#795548', 'Cinnamon, cardamom, and star anise provide powerful anti-inflammatory properties and aid in digestion.', false, false, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{"diet_halal": {"name": "Massaman Chicken", "description": "This curry has Muslim roots (''Mussulman''). We honor its heritage by using Halal chicken and ensuring total purity in the spice blend preparation.", "healthBenefits": "A historically Halal dish rich in warming spices.", "keyIngredients": ["Massaman Paste", "Potatoes", "Halal Chicken", "Roasted Peanuts", "Star Anise"]}, "diet_vegan": {"name": "Massaman Tofu", "description": "The ''Emperor of Curries''. We simmer potatoes, onions, and tofu in a rich sauce of cinnamon, star anise, and cardamom. Fish sauce is swapped for soy sauce for a deeply aromatic vegan stew.", "healthBenefits": "Cinnamon and Star Anise help regulate blood sugar levels.", "keyIngredients": ["Massaman Paste (No Shrimp)", "Potatoes", "Firm Tofu", "Roasted Peanuts", "Cinnamon"]}, "diet_kosher": {"name": "Massaman Tofu", "description": "We replace the shrimp paste with salt and use tofu instead of meat to keep this rich coconut curry Pareve and compliant with Kashrut standards.", "healthBenefits": "Rich spices support digestion and metabolism.", "keyIngredients": ["Massaman Paste (Salt Base)", "Potatoes", "Firm Tofu", "Roasted Peanuts", "Cinnamon"]}, "diet_jainism": {"name": "Massaman Pumpkin", "description": "Since traditional Massaman uses potatoes and onions (roots), we adapt this recipe using Pumpkin and unripe Banana, with a special root-free spice paste.", "healthBenefits": "A unique, root-free adaptation high in fiber and beta-carotene.", "keyIngredients": ["Massaman Spices", "Pumpkin", "Firm Tofu", "Roasted Peanuts", "Cinnamon"]}, "diet_hinduism": {"name": "Massaman Tofu", "description": "A beef-free version of this classic. We use tofu or paneer to absorb the complex flavors of Cardamom, Cinnamon, and Cloves in a rich coconut base.", "healthBenefits": "Warming spices improve circulation and mental clarity.", "keyIngredients": ["Massaman Paste", "Potatoes", "Firm Tofu", "Roasted Peanuts", "Cardamom"]}, "diet_meatlover": {"name": "Massaman Chicken", "description": "The world''s #1 delicious food (CNN Travel). Drumsticks or chicken chunks simmered until falling-off-the-bone tender in a rich, spice-laden coconut gravy with potatoes.", "healthBenefits": "Comfort food that warms the body and soothes the spirit.", "keyIngredients": ["Massaman Paste", "Potatoes", "Chicken", "Roasted Peanuts", "Cinnamon"]}, "diet_rastafari": {"name": "Ital Massaman", "description": "A pot of natural goodness. We use unrefined coconut sugar and natural tamarind to balance the flavors, simmering root vegetables (ground provisions) in coconut milk.", "healthBenefits": "Natural sweetness and spices without processed sugar.", "keyIngredients": ["Massaman Spices", "Potatoes", "Tofu", "Roasted Peanuts", "Tamarind"]}, "diet_vegetarian": {"name": "Massaman Tofu", "description": "Mild, sweet, and tangy. This curry uses Persian dry spices like Cardamom and Cinnamon. We serve it with soft potatoes and tofu for a comforting vegetarian bowl.", "healthBenefits": "Anti-inflammatory spices combined with heart-healthy peanuts.", "keyIngredients": ["Massaman Paste (No Shrimp)", "Potatoes", "Firm Tofu", "Roasted Peanuts", "Cardamom"]}, "diet_pescatarian": {"name": "Massaman Prawns", "description": "A unique twist on the classic. The sweet and sour tamarind base of Massaman pairs surprisingly well with the sweetness of river prawns.", "healthBenefits": "Tamarind aids digestion while spices boost immunity.", "keyIngredients": ["Massaman Paste", "Potatoes", "Fresh Prawns", "Roasted Peanuts", "Tamarind"]}}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'thai-massaman-curry', 'Thai Massaman Curry', 'Cook the world-famous Massaman Curry. Blend Persian dry spices, roasted peanuts, and coconut cream to perfection at Thai Akha Kitchen in Chiang Mai.', '{"massaman curry","southern thai curry","authentic massaman","chiang mai cooking class"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'curry-04', 'Rich Persian-Spiced Curry', 'A mild, rich, and deeply spiced stew blending Thai coconut cream with warm Persian dry spices.', '{"name": "Thai Massaman Curry", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "massaman curry, southern thai curry, authentic massaman, chiang mai cooking class", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Cook the world-famous Massaman Curry. Blend Persian dry spices, roasted peanuts, and coconut cream to perfection at Thai Akha Kitchen in Chiang Mai.", "recipeCuisine": "Thai", "recipeCategory": "curry"}'),
	('dess_01', 'Mango Sticky Rice', 'ข้าวเหนียวมะม่วง', 'Sweet coconut sticky rice served with perfectly ripe honey mango.', true, true, 'dessert', false, false, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', 1, '#FFC107', 'Fresh honey mangoes deliver a massive boost of Vitamin A and C for skin health.', false, true, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'mango-sticky-rice', 'Mango Sticky Rice', 'Sweeten your day with authentic Mango Sticky Rice. Learn the traditional method of steaming glutinous rice with coconut milk in our Chiang Mai class.', '{"mango sticky rice","khao niao mamuang","thai dessert","chiang mai cooking class"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'dessert-01', 'Sweet Coconut Rice & Fresh Mango', 'The quintessential Thai dessert combining sweet coconut-infused glutinous rice with perfectly ripe honey mangoes.', '{"name": "Mango Sticky Rice", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "mango sticky rice, khao niao mamuang, thai dessert, chiang mai cooking class", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Sweeten your day with authentic Mango Sticky Rice. Learn the traditional method of steaming glutinous rice with coconut milk in our Chiang Mai class.", "recipeCuisine": "Thai", "recipeCategory": "dessert"}'),
	('stirfry_03', 'Stir Fry Holy Basil', 'ผัดกะเพรา', 'A spicy street-food favorite with the aroma of holy basil.', true, true, 'stirfry', false, false, false, true, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', 3, '#1B5E20', 'Holy Basil acts as a powerful natural adaptogen that helps the body cope with stress.', false, false, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'stir-fry-holy-basil', 'Stir Fry Holy Basil', 'Master Pad Kra Pao, the legendary Thai Holy Basil stir-fry. Learn how to achieve the authentic street-food flavor in our Chiang Mai cooking school.', '{"pad kra pao","holy basil stir fry","thai street food","chiang mai cooking school"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'stirfry-03', 'Spicy Holy Basil Wok', 'A fiery and aromatic holy basil stir-fry that brings the authentic taste of Thai street markets.', '{"name": "Stir Fry Holy Basil", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "pad kra pao, holy basil stir fry, thai street food, chiang mai cooking school", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Master Pad Kra Pao, the legendary Thai Holy Basil stir-fry. Learn how to achieve the authentic street-food flavor in our Chiang Mai cooking school.", "recipeCuisine": "Thai", "recipeCategory": "stirfry"}'),
	('curry_01', 'Thai Red Curry', 'Gaeng Phet', 'Red curry is the original Thai curry with its paste made from sun dried red chilies (red sun-dried Anaheim peppers). The original version ("gaeng phet bpaa" or "wild red curry") was made with water instead of coconut milk. If you don''t like coconut, you can use cooking oil instead of coconut cream, and replace coconut milk with water.', true, true, 'curry', false, true, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', 3, '#D32F2F', 'Sun-dried red chilies are packed with capsaicin, naturally boosting metabolism and improving blood circulation.', false, false, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{"diet_halal": {"name": "Red Curry Chicken", "description": "Prepared with strict adherence to purity. We use certified poultry or tofu upon request, ensuring no pork products or alcohol ever touch the wok or the curry paste.", "healthBenefits": "Clean, wholesome protein balanced with digestive herbs.", "keyIngredients": ["Red Curry Paste", "Coconut Milk", "Halal Chicken", "Thai Eggplant", "Sweet Basil"]}, "diet_vegan": {"name": "Red Curry with Tofu", "description": "A vibrant, aromatic curry where the sweetness of the coconut cream meets the earthy depth of mushrooms and firm tofu. We use premium sea salt instead of shrimp paste to create a clean, powerful umami without any animal products.", "healthBenefits": "High in plant protein and capsaicin for circulation, with zero cholesterol.", "keyIngredients": ["Red Curry Paste (No Shrimp)", "Coconut Milk", "Firm Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_kosher": {"name": "Red Curry with Tofu", "description": "A customized version respecting Kashrut laws. We strictly replace the traditional shrimp paste with sea salt to exclude shellfish, and use tofu to avoid any meat-dairy mixing issues with the coconut milk.", "healthBenefits": "A pure, kosher-friendly adaptation rich in botanical nutrients.", "keyIngredients": ["Red Curry Paste (Salt Base)", "Coconut Milk", "Firm Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_jainism": {"name": "Red Curry Jai", "description": "A special root-free preparation. We create a custom paste omitting garlic, shallots, and galangal roots, using only the aromatic leaves and spices to respect the soil life.", "healthBenefits": "Sattvic food that warms the body without exciting the senses.", "keyIngredients": ["Red Chili (Seed Only)", "Coconut Milk", "Firm Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_hinduism": {"name": "Red Curry with Tofu", "description": "Respecting the sacredness of life, we omit all beef and often poultry, using firm tofu or paneer-style soy curds. The sauce is enriched with coconut cream for a luxurious texture.", "healthBenefits": "A harmonious blend that balances the internal fire (Agni) without heaviness.", "keyIngredients": ["Red Curry Paste", "Coconut Milk", "Firm Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_meatlover": {"name": "Red Curry Chicken", "description": "The original heavy-hitter. Sliced chicken breast absorbs the spicy coconut broth, while the traditional shrimp paste provides the authentic depth of flavor known as ''Gup Gam''.", "healthBenefits": "High protein content with the immune-boosting power of Galangal and Lemongrass.", "keyIngredients": ["Red Curry Paste", "Coconut Milk", "Chicken Breast", "Thai Eggplant", "Sweet Basil"]}, "diet_rastafari": {"name": "Ital Red Curry", "description": "Vital cooking at its best. We strip away processed sauces and use natural sea salt and fresh herbs to season the coconut broth, focusing on the life energy of the fresh vegetables.", "healthBenefits": "Maximizes ''Livity'' (Life Energy) with unprocessed, natural ingredients.", "keyIngredients": ["Red Curry Paste (Pure)", "Coconut Milk", "Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_vegetarian": {"name": "Red Curry with Tofu", "description": "The classic red curry experience, focusing on the harmony between the spicy paste and creamy coconut milk. Prepared with firm tofu and fresh vegetables, omitting the traditional shrimp paste for a pure vegetarian profile.", "healthBenefits": "Capsaicin boosts metabolism while coconut milk provides essential healthy fats.", "keyIngredients": ["Red Curry Paste (No Shrimp)", "Coconut Milk", "Firm Tofu", "Thai Eggplant", "Sweet Basil"]}, "diet_pescatarian": {"name": "Red Curry River Prawns", "description": "The authentic ocean version. We use fresh river prawns which perfectly amplify the traditional Kapi (shrimp paste) in the curry base for a deeply savory and aromatic experience.", "healthBenefits": "Rich in Omega-3 from prawns and antioxidants from the sun-dried red chilies.", "keyIngredients": ["Red Curry Paste", "Coconut Milk", "River Prawns", "Thai Eggplant", "Sweet Basil"]}}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'thai-red-curry', 'Thai Red Curry', 'Pound your own Red Curry paste from scratch. Learn to blend sun-dried red chilies and fresh herbs into a rich coconut curry at Thai Akha Kitchen.', '{"thai red curry","gaeng phet","red curry paste from scratch","chiang mai cooking class"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'curry-01', 'Rich & Spicy Coconut Curry', 'A bold and spicy coconut curry made from sun-dried red chilies pounded with fresh aromatic herbs.', '{"name": "Thai Red Curry", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/Recipes01.jpg", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "thai red curry, gaeng phet, red curry paste from scratch, chiang mai cooking class", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Pound your own Red Curry paste from scratch. Learn to blend sun-dried red chilies and fresh herbs into a rich coconut curry at Thai Akha Kitchen.", "recipeCuisine": "Thai", "recipeCategory": "curry"}'),
	('akha_01', 'Akha Mountain Fresh Salad', 'ยำผักชีดอย', 'A refreshing explosion of mountain herbs. Unlike typical Thai salads, this uses "Phak Chi Doi" (Mountain Coriander) and large cucumbers, gently bruised in a wooden mortar to absorb the dressing without losing the crunch.', true, true, 'akha_specialty', true, false, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/akha_salad_01.webp', 1, '#2E7D32', 'Wild mountain herbs act as traditional Akha medicine to cleanse the body and promote vitality.', true, true, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{"diet_halal": {"name": "Akha Salad Halal Friendly", "description": "Prepared with strictly alcohol-free seasonings and compliant sauces. A clean, herbal dish that respects Halal purity standards.", "healthBenefits": "Natural, clean ingredients compliant with Islamic dietary laws.", "keyIngredients": ["Mountain Coriander", "Ginger", "Roasted Peanuts", "Chili", "Halal Soy Sauce", "Lime"]}, "diet_vegan": {"name": "Akha Salad Plant-Based", "description": "A crisp, refreshing mountain mix. We replace fish sauce with premium soy sauce to maintain the savory depth without any animal products.", "healthBenefits": "Pure plant energy rich in fiber and essential oils.", "keyIngredients": ["Mountain Coriander", "Ginger", "Roasted Peanuts", "Chili", "Soy Sauce", "Lime"]}, "diet_kosher": {"name": "Akha Salad Kosher Friendly", "description": "We ensure no shellfish traces are present in the seasoning. Using sea salt or soy instead of fish products to guarantee Kashrut compliance.", "healthBenefits": "Pareve preparation suitable for any meal combination.", "keyIngredients": ["Mountain Coriander", "Ginger", "Roasted Peanuts", "Chili", "Sea Salt", "Lime"]}, "diet_jainism": {"name": "Akha Salad Ahimsa (No Roots)", "description": "Adapted for Ahimsa. We strictly exclude ginger, garlic, and onions, focusing solely on the surface-growing herbs and peanuts.", "healthBenefits": "Non-violent consumption respecting plant life cycles.", "keyIngredients": ["Mountain Coriander", "Roasted Peanuts", "Fresh Chili", "Soy Sauce", "Lime", "Cucumber"]}, "diet_regular": {"name": "Akha Salad Classic", "description": "A vibrant explosion of mountain coriander, ginger, and roasted peanuts. We use a dash of fish sauce to bring out the umami of the fresh herbs.", "healthBenefits": "High in antioxidants and vitamin C from fresh lime and herbs.", "keyIngredients": ["Mountain Coriander", "Ginger", "Roasted Peanuts", "Chili", "Fish Sauce", "Lime"]}, "diet_hinduism": {"name": "Akha Salad Sattvic Style", "description": "A light, clarifying salad prepared without garlic or strong onions to maintain mental clarity and spiritual balance.", "healthBenefits": "Promotes lightness and clarity of mind.", "keyIngredients": ["Mountain Coriander", "Ginger", "Roasted Peanuts", "Mild Chili", "Soy Sauce", "Lime"]}, "diet_meatlover": {"name": "Akha Salad Traditional", "description": "While this is a vegetable-forward dish, we prepare it with the robust, traditional fish sauce flavor that pairs perfectly with grilled meats.", "healthBenefits": "A perfect palate cleanser to balance protein-heavy meals.", "keyIngredients": ["Mountain Coriander", "Ginger", "Roasted Peanuts", "Chili", "Fish Sauce", "Lime"]}, "diet_rastafari": {"name": "Akha Salad Ital Style", "description": "Pure vitality from the earth. We minimize salt and processed sauces, relying on the natural ''Livity'' of fresh lime and spicy chili.", "healthBenefits": "Maximum life energy with minimal sodium processing.", "keyIngredients": ["Mountain Coriander", "Ginger", "Roasted Peanuts", "Fresh Chili", "Natural Herbs", "Lime"]}, "diet_vegetarian": {"name": "Akha Salad Vegetarian", "description": "A crisp, refreshing mountain mix adapted for a vegetarian diet, using savory soy sauce to maintain the depth of the herbs.", "healthBenefits": "Herbal detox properties combined with savory minerals.", "keyIngredients": ["Mountain Coriander", "Ginger", "Roasted Peanuts", "Chili", "Soy Sauce", "Lime"]}, "diet_pescatarian": {"name": "Akha Salad with Dried Shrimp", "description": "The traditional village version enhanced with sun-dried river shrimp for a salty, savory kick.", "healthBenefits": "Provides essential fatty acids and protein from dried shrimp.", "keyIngredients": ["Mountain Coriander", "Dried River Shrimp", "Roasted Peanuts", "Fish Sauce"]}}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'akha-salad', 'Akha Mountain Fresh Salad', 'Discover the Akha Mountain Fresh Salad. Learn indigenous hill-tribe culinary traditions using wild coriander and fresh herbs at Thai Akha Kitchen.', '{"akha mountain salad","phak chi doi","hill tribe food","akha cooking class chiang mai"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/akha_salad_01.webp', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'akha-specialty-01', 'Wild Mountain Herb Mix', 'A refreshing hill-tribe specialty made with wild mountain coriander, crisp cucumber, and a savory dressing.', '{"name": "Akha Mountain Fresh Salad", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/akha_salad_01.webp", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "akha mountain salad, phak chi doi, hill tribe food, akha cooking class chiang mai", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Discover the Akha Mountain Fresh Salad. Learn indigenous hill-tribe culinary traditions using wild coriander and fresh herbs at Thai Akha Kitchen.", "recipeCuisine": "Akha", "recipeCategory": "akha_specialty"}'),
	('akha_02', 'Akha Spirit Detox Soup', 'ซุปฟักเขียว', 'A crystal clear broth that heals the soul. Traditionally, meat is strictly forbidden in this dish to maintain spiritual purity. We use Winter Melon, ginger, and smashed herbs to create a restorative tonic.', true, true, 'akha_specialty', false, false, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/akha_soup_01.webp', 3, '#B71C1C', 'Winter melon and smashed ginger create a restorative tonic that purifies the digestive system.', true, true, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{"diet_halal": {"name": "Akha Soup Halal Friendly", "description": "A pure vegetable broth prepared in separate cookware to ensure zero contact with non-Halal ingredients.", "healthBenefits": "Pure, clean hydration compliant with dietary laws.", "keyIngredients": ["Mustard Greens", "Dill", "Spring Onions", "Garlic", "Sea Salt"]}, "diet_vegan": {"name": "Akha Soup Vegan", "description": "Naturally vegan by tradition. We enhance the broth with extra mushrooms and fresh herbs for a deep, savory flavor without any animal products.", "healthBenefits": "Alkalizing broth perfect for detox.", "keyIngredients": ["Mustard Greens", "Dill", "Mushrooms", "Coriander", "Garlic", "Sea Salt"]}, "diet_kosher": {"name": "Akha Soup Kosher Friendly", "description": "Strictly Pareve. A clear vegetable broth made with checked greens and pure sea salt, ensuring no shellfish or prohibited additives.", "healthBenefits": "Clean, neutral broth suitable for meat or dairy meals.", "keyIngredients": ["Mustard Greens", "Dill", "Spring Onions", "Garlic", "Sea Salt"]}, "diet_jainism": {"name": "Akha Soup Jain (No Roots)", "description": "A challenge we accept! We create a flavorful broth without garlic, onions, or coriander roots, using only leafy herbs like Dill and Mustard Greens.", "healthBenefits": "Digests easily without disturbing root systems.", "keyIngredients": ["Mustard Greens", "Dill", "Leafy Coriander", "Spinach", "Sea Salt"]}, "diet_regular": {"name": "Akha Herbal Soup", "description": "A restorative clear broth. Historically, this soup is 100% plant-based, using the natural oils of herbs rather than meat stock.", "healthBenefits": "Clears the respiratory system and warms the body.", "keyIngredients": ["Mustard Greens", "Dill", "Spring Onions", "Coriander Root", "Garlic", "Salt"]}, "diet_hinduism": {"name": "Akha Soup Sattvic", "description": "A pure, calming broth prepared without garlic or strong onions, perfect for maintaining a meditative state of mind.", "healthBenefits": "Cooling and purifying for the body.", "keyIngredients": ["Mustard Greens", "Dill", "Soft Tofu", "Sea Salt", "Mild Herbs"]}, "diet_meatlover": {"name": "Grandma''s Winter Soup", "description": "Even for meat lovers, this soup remains traditionally plant-based to cleanse the palate between rich meat dishes. Alternatively, slow-cooked pork ribs can be added.", "healthBenefits": "Balances a high-protein meal with digestive herbs.", "keyIngredients": ["Winter Melon", "Pork Ribs", "Ginger", "Black Pepper", "Mustard Greens"]}, "diet_rastafari": {"name": "Akha Soup Ital", "description": "Natural healing broth. We use no processed stock cubes, relying only on the vital energy of fresh green herbs and clean water.", "healthBenefits": "Restores ''Livity'' and hydration naturally.", "keyIngredients": ["Mustard Greens", "Dill", "Spring Onions", "Fresh Herbs", "Natural Salt"]}, "diet_vegetarian": {"name": "Akha Soup Vegetarian", "description": "A comforting, clear vegetable soup. We use soft tofu to add texture and protein to the aromatic herbal broth.", "healthBenefits": "Light, hydrating, and rich in vitamins.", "keyIngredients": ["Mustard Greens", "Dill", "Soft Tofu", "Spring Onions", "Garlic", "Salt"]}, "diet_pescatarian": {"name": "Akha Soup Clear Broth", "description": "We keep the traditional plant-based base but can season with a drop of fish sauce for that oceanic umami kick if desired.", "healthBenefits": "Hydrating broth with essential minerals.", "keyIngredients": ["Mustard Greens", "Dill", "Spring Onions", "Garlic", "Fish Sauce (Optional)", "Salt"]}}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/bg-04.webp}', 'akha-herbal-soup', 'Akha Spirit Detox Soup', 'Cleanse your palate with the Akha Spirit Detox Soup. Experience the authentic purifying broth made from winter melon and mountain herbs in Chiang Mai.', '{"akha spirit detox soup","winter melon soup","hill tribe recipes","chiang mai cooking school"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/akha_soup_01.webp', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'akha-specialty-02', 'Restorative Clear Winter Melon Broth', 'A restorative and clear winter melon broth traditionally used to cleanse the body and spirit.', '{"name": "Akha Spirit Detox Soup", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/akha_soup_01.webp", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "akha spirit detox soup, winter melon soup, hill tribe recipes, chiang mai cooking school", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Cleanse your palate with the Akha Spirit Detox Soup. Experience the authentic purifying broth made from winter melon and mountain herbs in Chiang Mai.", "recipeCuisine": "Akha", "recipeCategory": "akha_specialty"}'),
	('app_01', 'Papaya Salad', 'ส้มตำ', 'Traditional green papaya salad prepared authentically with mortar and pestle. Fresh, crunchy, and tangy.', true, true, 'appetizer', true, true, false, false, 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/papaya_salad_01.webp', 2, '#222420', 'Raw green papaya is rich in papain enzymes that significantly improve digestion and metabolism.', true, true, '2026-01-21 14:31:01.786845+00', '2026-04-05 12:50:04.97699+00', '{}', '{https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/papaya_salad_01.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/papaya_salad_01.webp,https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/papaya_salad_01.webp}', 'papaya-salad', 'Papaya Salad', 'Discover the authentic Som Tum (Papaya Salad) recipe. Learn to balance sweet, sour, and spicy flavors perfectly at Thai Akha Kitchen in Chiang Mai.', '{"som tum recipe","papaya salad chiang mai","authentic thai cooking","thai appetizers"}', 'index, follow', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/papaya_salad_01.webp', true, '2026-04-04 10:17:14.711059+00', 'Niti Muelaeku', 'appetizer-01', 'Traditional Hand-Pounded Salad', 'A vibrant, hand-pounded green papaya salad that perfectly balances sweet, sour, and spicy flavors.', '{"name": "Papaya Salad", "@type": "Recipe", "image": "https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Recipes/papaya_salad_01.webp", "author": {"name": "Niti Muelaeku", "@type": "Person"}, "@context": "https://schema.org/", "cookTime": "PT20M", "keywords": "som tum recipe, papaya salad chiang mai, authentic thai cooking, thai appetizers", "prepTime": "PT15M", "totalTime": "PT35M", "description": "Discover the authentic Som Tum (Papaya Salad) recipe. Learn to balance sweet, sour, and spicy flavors perfectly at Thai Akha Kitchen in Chiang Mai.", "recipeCuisine": "Thai", "recipeCategory": "appetizer"