INSERT INTO "public"."page_sections" ("section_id", "page_slug", "tag_badge", "title", "highlight", "subtitle", "description", "created_at", "updated_at") VALUES
	('history-01', 'history', 'Heritage', 'The Akha Heritage & Culture', 'Heritage & Culture', 'Discover the journey and living culture of the Akha people', 'Dive deep into the rich cultural roots of the Akha hill tribe. From their historical migration from the Tibetan Plateau to their sacred traditions, oral folklore, and sustainable way of life.', '2026-03-22 12:51:33.243382+00', '2026-03-22 12:51:33.243382+00'),
	('class-01', 'classes', 'Gallery', 'Kitchen', 'Life Stream', 'A visual journey into our daily kitchen life', 'Experience the vibrant atmosphere, the roaring wok fires, and the authentic joy of our outdoor Akha kitchen.', '2026-03-20 13:54:40.260788+00', '2026-03-29 12:56:11.997555+00'),
	('class-02', 'classes', 'Experience', '6 Reasons', 'to Join', 'Why we are the #1 cooking experience in Chiang Mai', 'Discover why we are the most authentic cooking experience in Chiang Mai. From organic farm ingredients to traditional Akha techniques.', '2026-03-20 13:54:40.260788+00', '2026-03-29 12:56:11.997555+00'),
	('class-03', 'classes', 'Culture', 'Our Story', '& Heritage', 'Explore our heritage and the colors of the hills', 'We share the deep history, vibrant culture, and daily lifestyle of the Akha hill tribe through our authentic food.', '2026-03-20 13:54:40.260788+00', '2026-03-29 12:56:11.997555+00'),
	('class-04', 'classes', 'Important Info', 'Things to Know', 'Before the Class', 'Essential details for your culinary adventure', 'Everything you need to know about pickup times, dietary adjustments, what to wear, and how to prepare for your day.', '2026-03-20 13:54:40.260788+00', '2026-03-29 12:56:11.997555+00'),
	('class-05', 'classes', 'The Menu', 'Learn 11', 'Authentic Dishes', 'A complete culinary journey from market to table', 'Master the art of balancing sweet, sour, salty, bitter, and spicy. Prepare your own curry paste from scratch.', '2026-03-20 13:54:40.260788+00', '2026-03-29 12:56:11.997555+00'),
	('recipe-07', 'recipes', 'Wok', 'Master The Wok:', 'Stir-fry', 'Choose 1 of 4 classic wok dishes', 'Learn how to control the breath of the wok. Select your preferred recipe and cook it to perfection with custom spice.', '2026-03-20 19:29:46.160292+00', '2026-03-29 12:56:11.997555+00'),
	('recipe-06', 'recipes', 'Soups', 'Authentic', 'Thai Soups', 'Choose your favorite from 4 distinct recipes', 'Master the delicate balance of Thai broth. You will select one soup of your choice to prepare from scratch.', '2026-03-20 19:29:46.160292+00', '2026-03-29 12:56:11.997555+00'),
	('recipe-05', 'recipes', 'Curry', 'Hand-pounded', 'Curry Pastes', 'Make the paste from scratch', 'The heartbeat of our kitchen. Select your favorite curry, and pound fresh herbs in a stone mortar for vibrant flavor.', '2026-03-20 19:29:46.160292+00', '2026-03-29 12:56:11.997555+00'),
	('recipe-03', 'recipes', 'Appetizers', 'Traditional Thai', 'Appetizers', 'Fresh starters we all prepare together', 'We start our culinary journey by preparing fresh and delicious traditional starters. Every student will learn these classic recipes.', '2026-03-20 19:29:46.160292+00', '2026-03-29 12:56:11.997555+00'),
	('recipe-02', 'recipes', 'Akha Food', 'Signature', 'Akha Dishes', 'Discover our heritage through food', 'These traditional tribal recipes are fixed for everyone. Experience our culture by preparing authentic dishes passed down through generations.', '2026-03-20 19:29:46.160292+00', '2026-03-29 12:56:11.997555+00'),
	('recipe-01', 'recipes', '', 'Our 11-Dish', 'Authentic Menu', 'A complete journey from market to table', 'Experience a hands-on class where you prepare a full course meal. Choose your favorite recipes to cook at your station.', '2026-03-20 19:29:46.160292+00', '2026-03-29 12:56:11.997555+00'),
	('recipe-04', 'recipes', 'Desserts', 'Sweet Thai', 'Desserts', 'The perfect ending we all make together', 'No Thai meal is complete without a sweet treat. Learn how to prepare traditional desserts like our famous Mango Sticky Rice.', '2026-03-20 19:29:46.160292+00', '2026-03-29 12:56:11.997555+00'),
	('class-06', 'classes', 'Market Tour', 'Local Market', 'Tour', 'Same same, but different', 'Experience the real lifestyle of local people. See and taste different local products that you wouldn''t notice without our guide.', '2026-03-29 12:56:11.997555+00', '2026-03-29 12:56:11.997555+00'),
	('home_01', 'home', 'AI Expert Assistant', 'Meet Cherry,', 'Your Digital Host', 'Our official cultural ambassador', 'Available 24/7 via text or live voice, Cherry can help you choose recipes, manage dietary restrictions, or tell you the ancestral stories behind every dish.', '2026-03-31 13:43:19.595546+00', '2026-03-31 13:56:55.052157+00'),
	('home_02', 'home', 'Our World', 'Explore the', 'Kitchen', 'Discover our classes, recipes, and heritage.', 'Step into the heart of our culture. From the roaring wok fires of our daily classes to the quiet wisdom of the Akha Zang, experience a culinary journey that bridges ancient traditions with modern life.', '2026-03-31 13:43:19.595546+00', '2026-03-31 13:56:55.052157+00'),
	('quiz-02', 'user-quiz', 'XP System', 'How to', 'Play & Win', 'From Free Beers to our Ambassador Kit.', 'Every correct answer adds points to your profile. As your XP grows, your progress bar fills up, automatically unlocking rewards like a Free Beer (300 XP), a Thai Akha T-shirt (1000 XP), or our signature Cooking Apron (1500 XP). Select a category below to start your journey!', '2026-03-31 20:49:10.596459+00', '2026-03-31 20:49:14.065916+00'),
	('quiz-01', 'user-quiz', 'Akha Wisdom Path', 'Test Your Knowledge &', 'Unlock Rewards', 'Earn XP by completing modules and win exclusive physical prizes.', 'Welcome to the ultimate Thai Akha Kitchen gamification experience. Choose your path among Akha Culture, Recipes, Ingredients, and Chiang Mai Lifestyle. Answer questions to earn Experience Points (XP) and claim real-world rewards at our school!', '2026-03-31 20:49:10.596459+00', '2026-03-31 20:49:14.065916+00'),
	('home_04', 'home', 'Interactive Journey', 'The Akha', 'Wisdom Path', 'Test your knowledge and earn real rewards.', 'Challenge yourself with our interactive cultural quizzes. Unlock achievements, discover the secrets of the mountain tribes, and win exclusive rewards like our signature organic coffee or a traditional Akha apron.', '2026-03-31 15:08:40.477933+00', '2026-03-31 15:08:40.477933+00'),
	('home_03', 'home', 'Our Roots', 'Our Highland', 'Heritage', 'The journey from the Tibetan Plateau.', 'Immerse yourself in the rich history and traditions of the Akha people. From our ancient migration routes to the sacred Spirit Gates and the meaning of our silver headdresses.', '2026-03-31 15:08:40.477933+00', '2026-03-31 15:08:40.477933+00'),
	('recipe-00', 'recipes', '', 'Select Your', 'Dietary Style', '100% customizable authentic flavors', 'Before exploring the menu, please select your preferences from the tabs above. All our recipes can be adapted to be Vegan, Vegetarian, Gluten-Free, or tailored for food allergies to ensure absolute safety and authentic flavor.', '2026-04-04 12:07:52.242494+00', '2026-04-04 12:07:52.242494+00'),
	('auth_step1', 'auth', 'Secure Access', 'Welcome to', 'Thai Akha Kitchen', 'Your Digital Passport', 'Log in to access your personal menu hub, view your bookings, and discover our exclusive Akha recipes.', '2026-04-06 13:42:39.014391+00', '2026-04-06 13:42:39.014391+00'),
	('auth_step2', 'auth', 'Verification', 'Check your', 'Email Inbox', 'Secure One-Time Password', 'We have sent a secure verification code to your email address. Please enter it below to complete your login.', '2026-04-06 13:42:39.014391+00', '2026-04-06 13:42:39.014391+00');
INSERT INTO "public"."quiz_categories" ("id", "title", "subtitle", "description", "icon_name", "color_theme", "avatar_url", "cover_image_url", "display_order", "is_active", "created_at") VALUES
	('chiang-mai', 'Chiang Mai Lifestyle', 'The Rose of the North', 'Explore the rich history, temples, and daily life of Northern Thailand.', 'map', 'btn-s', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Avatar_Agents_1548/1920-Avatar-01-Ploy.webp', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 4, true, '2026-03-31 18:36:31.149299+00'),
	('ingredients', 'Ingredients Quiz', 'The Forager''s Pantry', 'Can you identify the fresh mountain herbs, spices, and roots from our local market?', 'eco', 'btn-p', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Avatar_Agents_1548/1920-Avatar-01-Ploy.webp', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 3, true, '2026-03-31 18:36:31.149299+00'),
	('recipes', 'Recipes Quiz', 'Master Our Signature Dishes', 'Master the secrets of our 11 signature dishes and traditional cooking methods.', 'menu_book', 'action', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Avatar_Agents_1548/1920-Avatar-01-Ploy.webp', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 2, true, '2026-03-31 18:36:31.149299+00'),
	('akha', 'Akha Culture Quiz', 'The Ancestral Way of Life', 'Test your knowledge on the traditions, history, and heritage of the Akha people.', 'trophy', 'quiz-p', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/Avatar_Agents_1548/1920-Avatar-01-Ploy.webp', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 1, true, '2026-03-31 18:36:31.149299+00');
INSERT INTO "public"."quiz_levels" ("id", "title", "subtitle", "image_url", "display_order", "is_active", "is_featured", "created_at", "category_id") VALUES
	(3, 'Culture Enthusiast', 'Understand the Akha migration journey and the sacred rules of the Spirit Gate.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 3, true, false, '2026-03-25 09:23:00.869986+00', 'akha'),
	(2, 'Festival Participant', 'Learn about the Swing Festival, sacred rituals, and the Village Square celebrations.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 2, true, false, '2026-03-25 09:23:00.869986+00', 'akha'),
	(1, 'Novice Explorer', 'Discover the origins, oral history, and musical heritage of the Akha people.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 1, true, false, '2026-03-25 09:23:00.869986+00', 'akha'),
	(16, 'Golden Triangle Guide', 'Expert knowledge of the region''s history and highland geography.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 3, true, false, '2026-03-31 18:53:02.202008+00', 'chiang-mai'),
	(15, 'Lanna Local', 'Discover Northern Thai customs, local language, and street food etiquette.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 2, true, false, '2026-03-31 18:53:02.202008+00', 'chiang-mai'),
	(14, 'City Wanderer', 'Navigate the Old City, ancient walls, and local Buddhist temples.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 1, true, false, '2026-03-31 18:53:02.202008+00', 'chiang-mai'),
	(13, 'Highland Forager', 'Master the secrets of the forest pantry and wild Akha ingredients.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 3, true, false, '2026-03-31 18:53:02.202008+00', 'ingredients'),
	(12, 'Spice Apprentice', 'Understand the engine of flavor, mortar techniques, and dry spices.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 2, true, false, '2026-03-31 18:53:02.202008+00', 'ingredients'),
	(11, 'Market Explorer', 'Identify fresh mountain herbs, roots, and local market vegetables.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 1, true, false, '2026-03-31 18:53:02.202008+00', 'ingredients'),
	(10, 'Akha Master Chef', 'Perfect the 11 signature dishes and traditional Akha cooking techniques.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 3, true, false, '2026-03-31 18:53:02.202008+00', 'recipes'),
	(9, 'Curry Crafter', 'Master the balance of sweet, sour, salty, and spicy in traditional pastes.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 2, true, false, '2026-03-31 18:53:02.202008+00', 'recipes'),
	(8, 'Wok Beginner', 'Learn the basics of stir-frying and authentic Thai street food.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 1, true, false, '2026-03-31 18:53:02.202008+00', 'recipes'),
	(7, 'Akha Guardian', 'Achieve ultimate mastery of the Akha Zang, proving your deep cultural knowledge.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 7, true, true, '2026-03-25 09:23:00.869986+00', 'akha'),
	(6, 'Highland Harvester', 'Explore sustainable farming, the forager''s pantry, and the rise of Akha coffee.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 6, true, false, '2026-03-25 09:23:00.869986+00', 'akha'),
	(5, 'Kitchen Apprentice', 'Master the art of the mortar, pestle, and signature Akha chili pastes.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 5, true, false, '2026-03-25 09:23:00.869986+00', 'akha'),
	(4, 'Cultural Weaver', 'Dive into the deep meaning behind traditional dress, beadwork, and silver coins.', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/showcase/1920-Akha-Lady.webp', 4, true, false, '2026-03-25 09:23:00.869986+00', 'akha');
