INSERT INTO "public"."quiz_questions" ("id", "module_id", "text", "options", "correct_index", "explanation", "display_order") VALUES
	('d1f1a001-0000-0000-0000-000000000001', 'b1f1a001-1111-4a1b-8c1d-000000000001', 'Where do the Akha ancestors originally trace their roots?', '["Tibetan Plateau", "Bangkok Lowlands", "Vietnamese Coast"]', 0, 'The Akha roots trace back to the Tibetan Plateau before moving southward to Yunnan.', 1),
	('d1f1a001-0000-0000-0000-000000000002', 'b1f1a001-1111-4a1b-8c1d-000000000001', 'When did Akha communities roughly begin settling in Thailand?', '["1700s", "Early 1900s", "1990s"]', 1, 'The migration into Northern Thailand began in the early 1900s, first settling in Chiang Rai.', 2),
	('d1f1a001-0000-0000-0000-000000000003', 'b1f1a001-1111-4a1b-8c1d-000000000001', 'Which Chinese province has the largest Akha population today?', '["Sichuan", "Yunnan", "Guangdong"]', 1, 'Around 240,000 Akha live primarily in Yunnan Province, China.', 3),
	('d1f1a001-0000-0000-0000-000000000004', 'b1f1a001-1111-4a1b-8c1d-000000000001', 'What is the official state classification of the Akha in China?', '["Hmong", "Hani", "Lisu"]', 1, 'In China, the Akha are officially classified by the state as the Hani people.', 4),
	('d1f1a001-0000-0000-0000-000000000005', 'b1f1a001-1111-4a1b-8c1d-000000000001', 'Approximately how many Akha live in Thailand today?', '["~80,000", "~500,000", "~1 Million"]', 0, 'There are approximately 80,000 Akha living in the Thai highlands today.', 5),
	('d1f1a001-0000-0000-0000-000000000006', 'b1f1a001-1111-4a1b-8c1d-000000000001', 'What linguistic family does the Akha language belong to?', '["Tai-Kadai", "Mon-Khmer", "Tibeto-Burman"]', 2, 'The Akha belong to the Tibeto-Burman linguistic family.', 6),
	('d1f1a001-0000-0000-0000-000000000007', 'b1f1a001-1111-4a1b-8c1d-000000000001', 'Which country is NOT part of the historical Akha migration path?', '["Myanmar", "Laos", "Malaysia"]', 2, 'The Akha migrated to Myanmar, Laos, and Vietnam, but not as far south as Malaysia.', 7),
	('d1f1a002-0000-0000-0000-000000000001', 'b1f1a002-1111-4a1b-8c1d-000000000002', 'What is the ''Pii Pa'' instrument made of?', '["Carved bone", "A fresh forest leaf", "Bamboo"]', 1, 'The Pii Pa is played using a fresh leaf stretched between the lips to mimic forest sounds.', 1),
	('d1f1a002-0000-0000-0000-000000000002', 'b1f1a002-1111-4a1b-8c1d-000000000002', 'What does the Akha drum primarily represent?', '["Warfare", "Unity and collective spirit", "Rainmaking"]', 1, 'The drum represents unity, reminding the community they are gathering as one.', 2),
	('d1f1a002-0000-0000-0000-000000000003', 'b1f1a002-1111-4a1b-8c1d-000000000002', 'How are the Akha metal gongs typically played?', '["Rapidly and aggressively", "Slowly and rhythmically", "Only by children"]', 1, 'Players strike the gong slowly and rhythmically, allowing the deep note to resonate fully.', 3),
	('d1f1a002-0000-0000-0000-000000000004', 'b1f1a002-1111-4a1b-8c1d-000000000002', 'What is the main material used for Akha flutes?', '["Silver", "Mountain Bamboo", "Animal Horn"]', 1, 'Flutes are handmade from local mountain bamboo, giving each a unique sound.', 4),
	('d1f1a002-0000-0000-0000-000000000005', 'b1f1a002-1111-4a1b-8c1d-000000000002', 'How is the traditional Bamboo Dance performed?', '["Jumping over fire", "Tapping parallel poles on the ground", "Balancing on tall stilts"]', 1, 'People rhythmically open and close parallel bamboo poles on the ground while dancers step between them.', 5),
	('d1f1a002-0000-0000-0000-000000000006', 'b1f1a002-1111-4a1b-8c1d-000000000002', 'What is a core belief regarding music played on a leaf?', '["It belongs to the Chief", "Music can come directly from nature", "It must be bought"]', 1, 'The leaf instrument shows that music does not need to be owned and comes directly from nature.', 6),
	('d1f1a002-0000-0000-0000-000000000007', 'b1f1a002-1111-4a1b-8c1d-000000000002', 'Why did young men historically play the Reed Mouth Organ?', '["To scare predators", "To express emotion during courtship", "To signal an enemy attack"]', 1, 'Young men played it to express emotion and attract attention during courtship.', 7),
	('d1f1a003-0000-0000-0000-000000000001', 'b1f1a003-1111-4a1b-8c1d-000000000003', 'How is traditional Akha history preserved?', '["Written in ancient books", "Carved on stone", "Sung and spoken orally"]', 2, 'The Akha historically had no written script; knowledge is passed down through songs and stories.', 1),
	('d1f1a003-0000-0000-0000-000000000002', 'b1f1a003-1111-4a1b-8c1d-000000000003', 'What is the common way of greeting in Akha?', '["Saying ''Hello''", "Asking ''Where are you going?''", "Bowing silently"]', 1, 'Instead of just saying hello, they ask ''Where are you going?'' or ''What are you doing here?''.', 2),
	('d1f1a003-0000-0000-0000-000000000003', 'b1f1a003-1111-4a1b-8c1d-000000000003', 'How do you say ''Hello / Hi'' in Akha?', '["Sawasdee", "O doo tu ma", "Gher ler"]', 1, '''O doo tu ma'' is the traditional way to say Hello or Hi.', 3),
	('d1f1a003-0000-0000-0000-000000000004', 'b1f1a003-1111-4a1b-8c1d-000000000003', 'Is there a direct Akha word for ''Goodbye''?', '["Yes", "No, they tell you to travel safely", "No, they just walk away"]', 1, 'There are no direct words for goodbye; instead, they tell you to travel safely.', 4),
	('d1f1a003-0000-0000-0000-000000000005', 'b1f1a003-1111-4a1b-8c1d-000000000003', 'How are kitchen skills passed to young people?', '["By reading recipe books", "By watching, listening, and helping", "By attending city schools"]', 1, 'Young people learn by observing and helping elders in the living classroom of the kitchen.', 5),
	('d1f1a003-0000-0000-0000-000000000006', 'b1f1a003-1111-4a1b-8c1d-000000000003', 'How did young men initiate courtship in the village square?', '["Writing love letters", "Singing poetic songs by the fire", "Giving expensive gifts"]', 1, 'In a culture without written letters, courtship was done through musical dialogue and songs.', 6),
	('d1f1a003-0000-0000-0000-000000000007', 'b1f1a003-1111-4a1b-8c1d-000000000003', 'What does the phrase ''Jaw sa do mie la'' mean?', '["Thank you", "How are you doing?", "I am hungry"]', 1, 'It is the traditional Akha phrase for ''How are you doing?''.', 7),
	('d2f2a001-0000-0000-0000-000000000001', 'b2f2a001-2222-4a1b-8c1d-000000000001', 'What is the Swing Festival (Yehkuja) commonly celebrated as?', '["Men''s New Year", "Women''s New Year", "Harvest End"]', 1, 'It is celebrated as Women''s New Year because women display their status and artistry.', 1),
	('d2f2a001-0000-0000-0000-000000000002', 'b2f2a001-2222-4a1b-8c1d-000000000001', 'What does ''Yehkuja'' literally translate to?', '["Eating bitter rice", "Flying high", "Golden harvest"]', 0, 'It translates to ''eating bitter rice'', acknowledging the dwindling food supply before the new harvest.', 2),
	('d2f2a001-0000-0000-0000-000000000003', 'b2f2a001-2222-4a1b-8c1d-000000000001', 'Who has the authority to build the Giant Swing?', '["The Blacksmith", "The Women", "The Village Leader (Dzoeuh Mah)"]', 2, 'The Dzoeuh Mah oversees its construction; it is a ritual instrument, not just a toy.', 3),
	('d2f2a001-0000-0000-0000-000000000004', 'b2f2a001-2222-4a1b-8c1d-000000000001', 'When does the Swing Festival take place?', '["In December", "Exactly 120 days after planting rice", "On the first full moon of Spring"]', 1, 'It usually falls in late August, exactly 120 days after the village plants its rice.', 4),
	('d2f2a001-0000-0000-0000-000000000005', 'b2f2a001-2222-4a1b-8c1d-000000000001', 'What happens to the Giant Swing after the festival ends?', '["It is burned", "It is left to decay naturally", "It is dismantled for firewood"]', 1, 'It is left standing to decay naturally, returning to the earth.', 5),
	('d2f2a001-0000-0000-0000-000000000006', 'b2f2a001-2222-4a1b-8c1d-000000000001', 'What does the swinging movement symbolize?', '["Flying to the moon", "The cycle of life, renewal, and fertility", "Escaping evil spirits"]', 1, 'The motion connects earth to sky, encouraging rice growth and the cycle of renewal.', 6),
	('d2f2a001-0000-0000-0000-000000000007', 'b2f2a001-2222-4a1b-8c1d-000000000001', 'What do women wear during the Swing Festival?', '["Casual clothes", "White robes", "Their best traditional clothing and ornaments"]', 2, 'Women wear the elaborate traditional items they spent the entire year making.', 7),
	('d2f2a002-0000-0000-0000-000000000001', 'b2f2a002-2222-4a1b-8c1d-000000000002', 'What was the primary function of the village square at night?', '["A marketplace", "A gathering place for courtship and music", "A sacred altar"]', 1, 'It was the heart of oral traditions where young people gathered to meet potential partners.', 1),
	('d2f2a002-0000-0000-0000-000000000002', 'b2f2a002-2222-4a1b-8c1d-000000000002', 'How did men invite women to the square?', '["Ringing a bell", "Lighting a fire and singing courtship songs", "Sending a messenger"]', 1, 'Men would light a fire and sing poetic songs, waiting for women to answer in musical dialogue.', 2),
	('d2f2a002-0000-0000-0000-000000000003', 'b2f2a002-2222-4a1b-8c1d-000000000002', 'What qualities did young men express through their songs?', '["Wealth and land", "Humor, intelligence, and respect", "Warfare skills"]', 1, 'Songs were a way to express personality, wit, and emotional intelligence.', 3),
	('d2f2a002-0000-0000-0000-000000000004', 'b2f2a002-2222-4a1b-8c1d-000000000002', 'What did the public wearing of a heavy headdress signal in the square?', '["A woman was of marriageable age", "A woman was already married", "She was a village elder"]', 0, 'Exchanging a girl''s cap for an adult headdress signaled readiness for courtship and marriage.', 4),
	('d2f2a002-0000-0000-0000-000000000005', 'b2f2a002-2222-4a1b-8c1d-000000000002', 'How did the community coordinate dancing in the square?', '["Using written sheet music", "Following repeating rhythmic drum patterns", "Dancing in complete silence"]', 1, 'Drums played repeating patterns to guide the dancers'' movements.', 5),
	('d2f2a002-0000-0000-0000-000000000006', 'b2f2a002-2222-4a1b-8c1d-000000000002', 'What happens in the square during Yehkuja (Swing Festival)?', '["A giant market", "Women perform traditional dances and songs", "Men compete in hunting"]', 1, 'Women take the main stage, performing dances and songs for the villagers.', 6),
	('d2f2a002-0000-0000-0000-000000000007', 'b2f2a002-2222-4a1b-8c1d-000000000002', 'Why didn''t young Akha write love letters?', '["Paper was forbidden", "The Akha had no traditional written script", "It was considered rude"]', 1, 'Without a written script, all courtship and relationship building was done orally and musically.', 7),
	('d2f2a003-0000-0000-0000-000000000001', 'b2f2a003-2222-4a1b-8c1d-000000000003', 'Where is the ancestral altar located inside the home?', '["Near the front door", "On the women''s side of the house", "In the center of the room"]', 1, 'The altar is traditionally placed in a corner on the women''s side of the house.', 1),
	('d2f2a003-0000-0000-0000-000000000002', 'b2f2a003-2222-4a1b-8c1d-000000000003', 'What is considered the most sacred place inside the home?', '["The windows", "The hearth (fire pit)", "The roof"]', 1, 'The hearth is sacred because the fire represents continuity between past generations and the living.', 2),
	('d2f2a003-0000-0000-0000-000000000003', 'b2f2a003-2222-4a1b-8c1d-000000000003', 'What items are typically offered to ancestral spirits?', '["Raw meat and coins", "Cooked food, water, and rice whiskey", "Only fresh fruit"]', 1, 'Families offer bits of cooked food, water, and rice whiskey to honor their ancestors.', 3),
	('d2f2a003-0000-0000-0000-000000000004', 'b2f2a003-2222-4a1b-8c1d-000000000003', 'When do families perform private rituals during the Swing Festival?', '["Only at midnight", "Alongside the public swinging and dancing", "Before the swing is built"]', 1, 'While public events happen outside, families conduct private offerings inside the home.', 4),
	('d2f2a003-0000-0000-0000-000000000005', 'b2f2a003-2222-4a1b-8c1d-000000000003', 'Why are special offerings made during the ''Monsoon Season''?', '["To stop the rain", "Because spirits wander more freely and may enter the village", "To cool down the house"]', 1, 'The wet season is the ''Spirits Season'', so offerings are made to drive away wandering spirits.', 5),
	('d2f2a003-0000-0000-0000-000000000006', 'b2f2a003-2222-4a1b-8c1d-000000000003', 'Who usually sits near the ancestral side during ceremonies?', '["Children", "Elders or ritual leaders", "Unmarried men"]', 1, 'Elders and ritual leaders sit near the ancestral side to maintain the spiritual connection.', 6),
	('d2f2a003-0000-0000-0000-000000000007', 'b2f2a003-2222-4a1b-8c1d-000000000003', 'What agricultural element is the primary focus of ancestor offerings?', '["The fertility of the rice", "The growth of coffee", "The hunting of deer"]', 0, 'Because rice has a soul and is essential to life, its fertility is the focus of these offerings.', 7),
	('d3f3a001-0000-0000-0000-000000000001', 'b3f3a001-3333-4a1b-8c1d-000000000001', 'What is the Akha name for the Spirit Gate?', '["Torii", "Loku-Pah", "Wat"]', 1, 'The sacred gate is called Loku-Pah.', 1),
	('d3f3a001-0000-0000-0000-000000000002', 'b3f3a001-3333-4a1b-8c1d-000000000001', 'What two realms does the gate separate?', '["Day and Night", "The domain of humans and the realm of spirits", "Two rival villages"]', 1, 'It filters out wild spirits and keeps protective energy inside the human domain.', 2),
	('d3f3a001-0000-0000-0000-000000000003', 'b3f3a001-3333-4a1b-8c1d-000000000001', 'What materials are used to build the gate?', '["Concrete and iron", "Wood and bamboo", "Carved stone"]', 1, 'It is constructed from simple forest materials to signify impermanence and renewal.', 3),
	('d3f3a001-0000-0000-0000-000000000004', 'b3f3a001-3333-4a1b-8c1d-000000000001', 'How often is the Spirit Gate rebuilt?', '["Every 10 years", "Annually", "Only when it breaks"]', 1, 'It is rebuilt every year as part of the village''s annual ritual cycle.', 4),
	('d3f3a001-0000-0000-0000-000000000005', 'b3f3a001-3333-4a1b-8c1d-000000000001', 'What is the strict rule for outsiders regarding the gate?', '["Never take a photo of it", "Never touch it", "Never look at it"]', 1, 'Touching the gate is a major taboo as it disturbs the spiritual filter (Pyaw) of the community.', 5),
	('d3f3a001-0000-0000-0000-000000000006', 'b3f3a001-3333-4a1b-8c1d-000000000001', 'Why do humans have to pass through the gate when returning from the forest?', '["To pay a toll", "To return to the safety of the human domain from the wild", "To clean their shoes"]', 1, 'The jungle is the domain of spirits; passing the gate ensures spirits do not follow them home.', 6),
	('d3f3a001-0000-0000-0000-000000000007', 'b3f3a001-3333-4a1b-8c1d-000000000001', 'Who is the only person authorized to initiate the rebuilding of the gate?', '["The Blacksmith", "The Village Leader (Dzoeuh Mah)", "The Mayor"]', 1, 'Only the Dzoeuh Mah has the spiritual authority to start this ritual.', 7),
	('d3f3a002-0000-0000-0000-000000000001', 'b3f3a002-3333-4a1b-8c1d-000000000002', 'What do the wooden carvings on the Spirit Gate depict?', '["Dragons", "Male and female figures", "Wild tigers"]', 1, 'They feature explicit male and female principles to represent fertility and continuity.', 1),
	('d3f3a002-0000-0000-0000-000000000002', 'b3f3a002-3333-4a1b-8c1d-000000000002', 'What is the dual purpose of these carvings?', '["Decoration and wealth", "Ward off evil spirits and entice favorable spirits", "Scare animals and attract tourists"]', 1, 'They act as a spiritual shield against illness while inviting blessings.', 2),
	('d3f3a002-0000-0000-0000-000000000003', 'b3f3a002-3333-4a1b-8c1d-000000000002', 'Where else might similar carvings be placed for protection?', '["On the roofs of villagers'' houses", "On the village well", "Inside the rice storage"]', 0, 'Roof carvings act as a secondary measure to control the flow of spirits into the home.', 3),
	('d3f3a002-0000-0000-0000-000000000004', 'b3f3a002-3333-4a1b-8c1d-000000000002', 'Are the carvings meant to be permanent stone monuments?', '["Yes", "No, they are made from temporary forest materials", "Yes, they are made of bronze"]', 1, 'They are carved from wood to reflect the Akha belief in renewal rather than permanence.', 4),
	('d3f3a002-0000-0000-0000-000000000005', 'b3f3a002-3333-4a1b-8c1d-000000000002', 'What internal house feature mimics the function of the Spirit Gate?', '["The windows", "Gender segregation zones", "The kitchen sink"]', 1, 'Houses are segregated by gender to maintain strict boundaries and spiritual order.', 5),
	('d3f3a002-0000-0000-0000-000000000006', 'b3f3a002-3333-4a1b-8c1d-000000000002', 'What do the female and male figures primarily ensure for the village?', '["Wealth", "Fertility", "Good weather"]', 1, 'They represent the continuity of life and fertility for the community.', 6),
	('d3f3a002-0000-0000-0000-000000000007', 'b3f3a002-3333-4a1b-8c1d-000000000002', 'What concept is maintained by these carvings and boundaries?', '["Karma", "Pyaw (Balance)", "Zen"]', 1, 'They protect the ''Pyaw'', the delicate balance between the human world and the spirit world.', 7),
	('d3f3a003-0000-0000-0000-000000000001', 'b3f3a003-3333-4a1b-8c1d-000000000003', 'Historically, why was the birth of twins considered ominous?', '["It meant bad weather", "Only animals were believed to give birth to multiple offspring", "It cost too much money"]', 1, 'Twins were viewed as unnatural and associated with the spirit world rather than the human one.', 1),
	('d3f3a003-0000-0000-0000-000000000002', 'b3f3a003-3333-4a1b-8c1d-000000000003', 'What type of death is considered a ''bad death'' requiring special purification?', '["Death by old age", "Death caused by a tiger", "Death in a neighboring village"]', 1, 'Tiger attacks are associated with powerful and dangerous spiritual forces.', 2),
	('d3f3a003-0000-0000-0000-000000000003', 'b3f3a003-3333-4a1b-8c1d-000000000003', 'What happens if someone touches the Spirit Gate?', '["They get rich", "They disturb the spiritual balance of the entire village", "Nothing"]', 1, 'Touching the gate breaks the spiritual filter, which is a major taboo.', 3),
	('d3f3a003-0000-0000-0000-000000000004', 'b3f3a003-3333-4a1b-8c1d-000000000003', 'How many unknowable things from the jungle are forbidden to eat?', '["Three", "Ten", "None"]', 0, 'The taboo of the ''Three Unknowable Things'' teaches restraint and respect for nature.', 4),
	('d3f3a003-0000-0000-0000-000000000005', 'b3f3a003-3333-4a1b-8c1d-000000000003', 'What is the strict marriage taboo in Akha society?', '["Marrying before 20", "Sharing a common male ancestor within the last six generations", "Marrying someone from a different village"]', 1, 'To prevent incest and protect social order, couples with a shared ancestor within 6 generations cannot marry.', 5),
	('d3f3a003-0000-0000-0000-000000000006', 'b3f3a003-3333-4a1b-8c1d-000000000003', 'What season is considered the ''Spirits Season'' when taboos are most critical?', '["The Dry Season", "The Monsoon (Wet) Season", "Winter"]', 1, 'During the wet season, spirits wander more freely and may enter the village.', 6),
	('d3f3a003-0000-0000-0000-000000000007', 'b3f3a003-3333-4a1b-8c1d-000000000003', 'Why are special burial rites performed after a ''bad death''?', '["To claim insurance", "To ensure harmful spiritual influences do not affect the community", "To punish the family"]', 1, 'Purification rituals restore balance and guide the deceased safely to the ancestral realm.', 7),
	('d4f4a001-0000-0000-0000-000000000001', 'b4f4a001-4444-4a1b-8c1d-000000000001', 'Which subgroup wears a pointed bamboo cone headdress?', '["Lomi Akha", "Pamee Akha", "Ulo Akha"]', 2, 'The Ulo Akha are distinct for their tall bamboo cone covered in beads and silver.', 1),
	('d4f4a001-0000-0000-0000-000000000002', 'b4f4a001-4444-4a1b-8c1d-000000000001', 'Which subgroup wears a flat, silver trapezoidal cap?', '["Pamee Akha", "Ulo Akha", "Lomi Akha"]', 0, 'The Pamee Akha wear a geometric trapezoid cap with long chains of silver rings.', 2),
	('d4f4a001-0000-0000-0000-000000000003', 'b4f4a001-4444-4a1b-8c1d-000000000001', 'Which subgroup wears a round plate framed with silver balls?', '["Ulo Akha", "Lomi Akha", "Pamee Akha"]', 1, 'The Lomi Akha style focuses on a rounded silhouette framed by metalwork.', 3),
	('d4f4a001-0000-0000-0000-000000000004', 'b4f4a001-4444-4a1b-8c1d-000000000001', 'How does a married Lomi woman modify her headdress?', '["She takes it off", "She attaches a trapezoidal inscribed plate to the back", "She paints it red"]', 1, 'This specific grammatical rule of dress signals that the Lomi woman is married.', 4),
	('d4f4a001-0000-0000-0000-000000000005', 'b4f4a001-4444-4a1b-8c1d-000000000001', 'What is placed at the very top of an Ulo headdress?', '["A diamond", "Dyed chicken feather tassels and a wool pom-pom", "A silver bell"]', 1, 'The pointed cone is adorned with dangling feathers and wool.', 5),
	('d4f4a001-0000-0000-0000-000000000006', 'b4f4a001-4444-4a1b-8c1d-000000000001', 'At what stage of life does a girl usually don the full adult headdress?', '["At birth", "In mid-adolescence (marriageable age)", "After her first child"]', 1, 'Exchanging a girl''s cap for the adult headdress signals she is of age to marry.', 6),
	('d4f4a001-0000-0000-0000-000000000007', 'b4f4a001-4444-4a1b-8c1d-000000000001', 'What hangs down the sides of a Pamee headdress?', '["Feathers", "Long chains of linked silver rings", "Wooden beads"]', 1, 'These heavy silver chains are the most recognizable feature of the Pamee style.', 7),
	('d4f4a002-0000-0000-0000-000000000001', 'b4f4a002-4444-4a1b-8c1d-000000000002', 'What does the dark blue/black base color of Akha fabric represent?', '["The night sky", "The earth and stability", "Sorrow"]', 1, 'Achieved through indigo dyeing, the dark color represents stability and the earth.', 1),
	('d4f4a002-0000-0000-0000-000000000002', 'b4f4a002-4444-4a1b-8c1d-000000000002', 'How is the raw cotton turned into thread?', '["Machine weaving", "Spun by hand using a spindle", "Bought at the market"]', 1, 'Akha women spin raw cotton entirely by hand using a traditional spindle.', 2),
	('d4f4a002-0000-0000-0000-000000000003', 'b4f4a002-4444-4a1b-8c1d-000000000002', 'What is the ''Jejaw''?', '["A hat", "A beaded sash worn over the skirt", "A type of shoe"]', 1, 'The Jejaw hangs down the front of the skirt to prevent it from flying up in the wind.', 3),
	('d4f4a002-0000-0000-0000-000000000004', 'b4f4a002-4444-4a1b-8c1d-000000000002', 'What part of the woman''s jacket is the primary canvas for embroidery?', '["The back", "The cuffs and lapels", "The inside lining"]', 1, 'The intricate needlework is concentrated on the cuffs and lapels of the loose-fitting jacket.', 4),
	('d4f4a002-0000-0000-0000-000000000005', 'b4f4a002-4444-4a1b-8c1d-000000000002', 'What is a ''sporran'' in Akha dress?', '["A silver necklace", "A decorative pouch beaded in white", "A heavy belt"]', 1, 'The short black skirt is accessorized with this white beaded pouch.', 5),
	('d4f4a002-0000-0000-0000-000000000006', 'b4f4a002-4444-4a1b-8c1d-000000000002', 'How does men''s clothing differ from women''s?', '["It is brighter", "It is simpler, uniform, and focused on utility", "They wear more silver"]', 1, 'Men wear functional indigo clothing without the elaborate silver and beadwork of the women.', 6),
	('d4f4a002-0000-0000-0000-000000000007', 'b4f4a002-4444-4a1b-8c1d-000000000002', 'What tool is used to weave the spun thread into cloth?', '["A foot-treadle loom", "A spinning wheel", "A knitting needle"]', 0, 'The thread is meticulously woven into cloth on a traditional foot-treadle loom.', 7),
	('d4f4a003-0000-0000-0000-000000000001', 'b4f4a003-4444-4a1b-8c1d-000000000003', 'What spiritual property is silver believed to possess?', '["It brings rain", "It protects against sickness and bad spirits", "It makes you invisible"]', 1, 'Silver is worn largely because it is believed to deflect evil and protect health.', 1),
	('d4f4a003-0000-0000-0000-000000000002', 'b4f4a003-4444-4a1b-8c1d-000000000003', 'What do the old coins on a headdress visually represent?', '["A portable bank and map of ancestral trade routes", "The number of children a woman has", "Her husband''s age"]', 0, 'Coins show family wealth and historical links to ancestors and trade.', 2),
	('d4f4a003-0000-0000-0000-000000000003', 'b4f4a003-4444-4a1b-8c1d-000000000003', 'What type of coins are typically used by wealthy Ulo families?', '["Thai Baht", "Silver Rupees", "Plastic tokens"]', 1, 'Wealthy families use older silver rupees, while poorer families might use Thai baht.', 3),
	('d4f4a003-0000-0000-0000-000000000004', 'b4f4a003-4444-4a1b-8c1d-000000000003', 'What does the heavy physical weight of the headdress signify?', '["Punishment", "Responsibility and adulthood", "Fashion"]', 1, 'The weight she carries on her head reflects the heavy responsibilities of an adult woman.', 4),
	('d4f4a003-0000-0000-0000-000000000005', 'b4f4a003-4444-4a1b-8c1d-000000000003', 'Do Akha men wear heavy silver headdresses to show status?', '["Yes, heavier than the women", "No, their status is not written on their clothes with silver", "Only on their birthdays"]', 1, 'Unlike women, men''s attire is uniform and their status is defined by social roles, not silver.', 5),
	('d4f4a003-0000-0000-0000-000000000006', 'b4f4a003-4444-4a1b-8c1d-000000000003', 'What does wearing the fully decorated headdress signal to the village men?', '["She is leaving the village", "She is of marriageable age", "She is a shaman"]', 1, 'It is a public sign that the adolescent girl is now ready for courtship.', 6),
	('d4f4a003-0000-0000-0000-000000000007', 'b4f4a003-4444-4a1b-8c1d-000000000003', 'How is the identity of a woman ''spoken'' without words?', '["By the color of her shoes", "Through every bead, coin, and stitch of her clothing", "By clapping her hands"]', 1, 'Traditional clothing is a language that shows subgroup, wealth, and marital status.', 7),
	('d5f5a001-0000-0000-0000-000000000001', 'b5f5a001-5555-4a1b-8c1d-000000000001', 'What tool is considered the ''engine of flavor'' in Akha cooking?', '["The oven", "The mortar and pestle", "The microwave"]', 1, 'It is essential because it crushes ingredients to release their deep flavors.', 1),
	('d5f5a001-0000-0000-0000-000000000002', 'b5f5a001-5555-4a1b-8c1d-000000000001', 'Why are herbs and chilies pounded instead of chopped?', '["Knives are forbidden", "Pounding releases essential oils and strong medicinal flavors", "It looks better"]', 1, 'Crushing breaks down the cell walls, releasing flavors that cutting cannot achieve.', 2),
	('d5f5a001-0000-0000-0000-000000000003', 'b5f5a001-5555-4a1b-8c1d-000000000001', 'What is the focal point of a traditional Akha meal?', '["A large steak", "The fiercely flavored chili dip in the center", "A sweet dessert"]', 1, 'Because the staple is simple rice, the meal relies on the complex flavors of the central dip.', 3),
	('d5f5a001-0000-0000-0000-000000000004', 'b5f5a001-5555-4a1b-8c1d-000000000001', 'What sound is commonly heard in an Akha village in the morning?', '["Car engines", "The rhythmic pounding of the mortar", "Televisions"]', 1, 'The sound of pounding ingredients for the daily Sapi Thong is a morning staple.', 4),
	('d5f5a001-0000-0000-0000-000000000005', 'b5f5a001-5555-4a1b-8c1d-000000000001', 'According to the Akha saying, salt brings the flavor, but what gives you passion?', '["Sugar", "Chilies", "Water"]', 1, '''Salt brings the flavor, but chilies give you a passion'' defines their seasoning philosophy.', 5),
	('d5f5a001-0000-0000-0000-000000000006', 'b5f5a001-5555-4a1b-8c1d-000000000001', 'Does Akha cooking rely heavily on added sugar?', '["Yes, heavily", "No, it relies on natural forest flavors", "Only in soups"]', 1, 'Seasoning is minimal and natural so the true taste of the forest remains.', 6),
	('d5f5a001-0000-0000-0000-000000000007', 'b5f5a001-5555-4a1b-8c1d-000000000001', 'Is an electric blender an acceptable substitute for traditional Akha paste?', '["Yes, it is faster", "No, ingredients must be pounded slowly by hand", "Only for tourists"]', 1, 'Blending cuts rather than crushes, altering the authentic texture and smell.', 7),
	('d5f5a002-0000-0000-0000-000000000001', 'b5f5a002-5555-4a1b-8c1d-000000000002', 'What is ''Sapi Thong''?', '["A dance", "The traditional tomato-chili dipping sauce", "A type of rice"]', 1, 'It is the signature dip eaten daily with rice and forest vegetables.', 1),
	('d5f5a002-0000-0000-0000-000000000002', 'b5f5a002-5555-4a1b-8c1d-000000000002', 'What makes ''Sapi Luu Neh Thong'' unique?', '["It uses charcoal-roasted, blistered ingredients", "It is very sweet", "It is served frozen"]', 0, '''Luu Neh'' means to roast; chilies and tomatoes are charred before pounding for a smoky flavor.', 2),
	('d5f5a002-0000-0000-0000-000000000003', 'b5f5a002-5555-4a1b-8c1d-000000000002', 'What is ''Ahchi''?', '["A wild mushroom", "Fermented soybean sheets", "A fish sauce"]', 1, 'Ahchi is toasted until crispy and pounded into the sauce as a savory protein supplement.', 3),
	('d5f5a002-0000-0000-0000-000000000004', 'b5f5a002-5555-4a1b-8c1d-000000000002', 'Which version is known as the ''lazy'' dip?', '["Sapi Zhar", "Makher Chare", "Luu Neh"]', 0, 'Sapi Zhar is made in minutes using simple chili flakes, salt, and water.', 4),
	('d5f5a002-0000-0000-0000-000000000005', 'b5f5a002-5555-4a1b-8c1d-000000000002', 'What are the base ingredients of the classic ''Makher Chare Sapi Thong''?', '["Boiled tomatoes, roasted peanuts, and mint", "Raw beef and chili", "Coconut milk and lime"]', 0, 'It is the everyday dip, often used to make vegetable wraps.', 5),
	('d5f5a002-0000-0000-0000-000000000006', 'b5f5a002-5555-4a1b-8c1d-000000000002', 'How is Sapi Thong typically eaten?', '["With a spoon like soup", "Shared and eaten with rice, veg, and grilled meat", "Spread on bread"]', 1, 'It is a communal dish that brings all parts of the meal together.', 6),
	('d5f5a002-0000-0000-0000-000000000007', 'b5f5a002-5555-4a1b-8c1d-000000000002', 'Why is Ahchi toasted before pounding?', '["To melt it", "To make it crispy and release its savory aroma", "To change its color"]', 1, 'Crispy Ahchi adds texture and deep umami flavor to the fermented dip.', 7),
	('d5f5a003-0000-0000-0000-000000000001', 'b5f5a003-5555-4a1b-8c1d-000000000003', 'How is traditional Akha highland rice watered?', '["Complex river irrigation", "Solely by seasonal rainfall (dry-land farming)", "Underground pipes"]', 1, 'Unlike lowland paddies, highland rice depends entirely on the monsoon rains.', 1),
	('d5f5a003-0000-0000-0000-000000000002', 'b5f5a003-5555-4a1b-8c1d-000000000003', 'How do the Akha view the nature of rice?', '["Just a simple carbohydrate", "It is alive and has a sensitive soul", "It is only for animals"]', 1, 'Rice is treated as a living entity with a soul that must be respected.', 2),
	('d5f5a003-0000-0000-0000-000000000003', 'b5f5a003-5555-4a1b-8c1d-000000000003', 'What action can frighten the soul of the rice?', '["Singing softly", "Loud shouting or anger in the fields", "Watering it"]', 1, 'Disrespectful words or loud noises can cause the rice soul to flee.', 3),
	('d5f5a003-0000-0000-0000-000000000004', 'b5f5a003-5555-4a1b-8c1d-000000000003', 'What is the consequence if the rice soul escapes?', '["The rice grows faster", "The harvest may fail", "The sky turns red"]', 1, 'A failed harvest is seen as a spiritual imbalance, not just an agricultural mistake.', 4),
	('d5f5a003-0000-0000-0000-000000000005', 'b5f5a003-5555-4a1b-8c1d-000000000003', 'How can elders call the rice soul back?', '["By burning the field", "Through quiet chants, gentle handling, and offerings", "By shooting guns"]', 1, 'Gentle rituals and offerings of food or rice wine restore harmony.', 5),
	('d5f5a003-0000-0000-0000-000000000006', 'b5f5a003-5555-4a1b-8c1d-000000000003', 'What agricultural event is the focus of major ancestor offerings?', '["Planting tomatoes", "The fertility of the rice", "Harvesting coffee"]', 1, 'Because rice is the spiritual staple, its fertility is paramount.', 6),
	('d5f5a003-0000-0000-0000-000000000007', 'b5f5a003-5555-4a1b-8c1d-000000000003', 'How often is rice typically eaten in the traditional Akha diet?', '["Once a week", "At every single meal", "Only on holidays"]', 1, 'It is the absolute center of the diet and eaten at every meal.', 7),
	('d6f6a001-0000-0000-0000-000000000001', 'b6f6a001-6666-4a1b-8c1d-000000000001', 'Who are the primary foragers in traditional Akha society?', '["The men", "The women", "The children"]', 1, 'While men hunt, women cross the Spirit Gate to gather plants and herbs.', 1),
	('d6f6a001-0000-0000-0000-000000000002', 'b6f6a001-6666-4a1b-8c1d-000000000001', 'What is the forest considered in Akha culture?', '["A dangerous wasteland", "The spiritual pantry and pharmacy", "A place only for men"]', 1, 'Food and medicine come directly from the forest, not the market.', 2),
	('d6f6a001-0000-0000-0000-000000000003', 'b6f6a001-6666-4a1b-8c1d-000000000001', 'What is a vital source of protein gathered from the forest by women?', '["Cow milk", "Insects", "Whale meat"]', 1, 'Insects provide essential protein and are gathered respectfully from the wild.', 3),
	('d6f6a001-0000-0000-0000-000000000004', 'b6f6a001-6666-4a1b-8c1d-000000000001', 'How many specific things from the jungle are strictly forbidden to eat?', '["Three", "Ten", "Everything is allowed"]', 0, 'The taboo of the ''Three Unknowable Things'' teaches restraint and respect.', 4),
	('d6f6a001-0000-0000-0000-000000000005', 'b6f6a001-6666-4a1b-8c1d-000000000001', 'What must women cross to enter the ''realm of spirits'' for foraging?', '["A river", "The Spirit Gate (Loku-Pah)", "A stone bridge"]', 1, 'Crossing the gate marks the transition from safety into the wild.', 5),
	('d6f6a001-0000-0000-0000-000000000006', 'b6f6a001-6666-4a1b-8c1d-000000000001', 'What is the core philosophy of Akha foraging?', '["Take everything you find", "Take only what is needed and harvest in season", "Burn the forest after gathering"]', 1, 'Foraging is done with deep respect to protect nature for the future.', 6),
	('4dc918c1-17bd-421e-89b1-29b85ca5b50e', 'fad7e3f8-8f3e-425c-b0f1-30753bd20d0f', 'What is considered the prized prey for Akha male hunters?', '["The barking deer", "Wild rabbits", "Jungle fowl"]', 0, 'The barking deer is considered the prized prey in the realm of spirits.', 3),
	('d6f6a001-0000-0000-0000-000000000007', 'b6f6a001-6666-4a1b-8c1d-000000000001', 'What is often believed to be the cause of illness?', '["Eating too much sugar", "A ''soul'' leaving the body or a spirit entering the village", "Lack of sleep"]', 1, 'Illness is viewed spiritually; eating correct foods from the forest maintains balance.', 7),
	('d6f6a002-0000-0000-0000-000000000001', 'b6f6a002-6666-4a1b-8c1d-000000000002', 'What major cash crop did coffee primarily replace in Akha villages?', '["Corn", "Opium", "Wheat"]', 1, 'Government bans on opium forced the transition to sustainable crops like coffee.', 1),
	('d6f6a002-0000-0000-0000-000000000002', 'b6f6a002-6666-4a1b-8c1d-000000000002', 'Why is coffee an ideal crop for Akha communities?', '["It grows underwater", "It grows well at high altitudes and supports soil stability", "It requires no rain"]', 1, 'High-altitude environments are perfect for Arabica beans, protecting the watershed.', 2),
	('d6f6a002-0000-0000-0000-000000000003', 'b6f6a002-6666-4a1b-8c1d-000000000002', 'What province is considered the heartland of Akha specialty coffee?', '["Phuket", "Chiang Rai", "Bangkok"]', 1, 'Chiang Rai (e.g., Doi Chang) is the center of highland coffee production.', 3),
	('d6f6a002-0000-0000-0000-000000000004', 'b6f6a002-6666-4a1b-8c1d-000000000002', 'What type of coffee bean is primarily grown by the Akha?', '["Robusta", "Arabica", "Liberica"]', 1, 'They cultivate high-quality Arabica, known for complex flavor profiles.', 4),
	('d6f6a002-0000-0000-0000-000000000005', 'b6f6a002-6666-4a1b-8c1d-000000000002', 'How has coffee changed the village economy?', '["Everyone moved to the city", "It created a blend of specialty coffee production and eco-tourism", "They stopped eating rice"]', 1, 'Villages now host cafes, roasteries, and homestays, securing economic sovereignty.', 5),
	('d6f6a002-0000-0000-0000-000000000006', 'b6f6a002-6666-4a1b-8c1d-000000000002', 'What is ''Akha Ama Coffee''?', '["A type of tea", "A flagship café showcasing specialty Akha beans and farmers'' stories", "A chemical fertilizer"]', 1, 'It is a famous brand in Chiang Mai that promotes fair-trade Akha coffee.', 6),
	('d6f6a002-0000-0000-0000-000000000007', 'b6f6a002-6666-4a1b-8c1d-000000000002', 'What agricultural method preserves the forest canopy during coffee cultivation?', '["Clear-cutting", "Shade-Grown farming", "Greenhouse planting"]', 1, 'Shade-grown coffee thrives under the natural forest canopy, protecting the ecosystem.', 7),
	('d6f6a003-0000-0000-0000-000000000001', 'b6f6a003-6666-4a1b-8c1d-000000000003', 'What type of pig is traditionally raised by the Akha?', '["Pink commercial pigs", "Black pigs", "Wild boars"]', 1, 'They raise black pigs, often reserved for ceremonial sacrifices or special guests.', 1),
	('d6f6a003-0000-0000-0000-000000000002', 'b6f6a003-6666-4a1b-8c1d-000000000003', 'What animal is considered the prized prey for Akha men hunting in the forest?', '["The Barking Deer", "The Elephant", "The Tiger"]', 0, 'Hunting is a favorite pastime, and the barking deer is highly prized.', 2),
	('d6f6a003-0000-0000-0000-000000000003', 'b6f6a003-6666-4a1b-8c1d-000000000003', 'What was the traditional farming style before modern restrictions?', '["Hydroponics", "Rotational mountain agriculture", "Monoculture"]', 1, 'They rotated crops in cycles that allowed the soil and forest to recover naturally.', 3),
	('d6f6a003-0000-0000-0000-000000000004', 'b6f6a003-6666-4a1b-8c1d-000000000003', 'What is the primary goal of Akha agricultural practices?', '["Maximum profit", "Balance, protecting soil fertility, and respecting ecosystems", "Exporting globally"]', 1, 'Farming is both a livelihood and a cultural responsibility to maintain balance.', 4),
	('d6f6a003-0000-0000-0000-000000000005', 'b6f6a003-6666-4a1b-8c1d-000000000003', 'Besides coffee, what are other common modern cash crops?', '["Apples and grapes", "Soybeans, cabbages, tomatoes, and chilies", "Coconuts"]', 1, 'These crops helped villages diversify their income after the opium ban.', 5),
	('d6f6a003-0000-0000-0000-000000000006', 'b6f6a003-6666-4a1b-8c1d-000000000003', 'What does ''Domain of Man'' refer to in Akha pantry terms?', '["The supermarket", "Cultivated crops grown inside the village boundary", "The deep jungle"]', 1, 'The pantry is split between cultivated crops (man) and wild foods (spirits).', 6),
	('d6f6a003-0000-0000-0000-000000000007', 'b6f6a003-6666-4a1b-8c1d-000000000003', 'Are large livestock like pigs eaten daily?', '["Yes, at every meal", "No, they are reserved for ceremonies or special guests", "They are never eaten"]', 1, 'Daily protein comes from smaller sources or foraging; pigs are for major events.', 7),
	('d7f7a001-0000-0000-0000-000000000001', 'b7f7a001-7777-4a1b-8c1d-000000000001', 'What does ''Akha Zang'' literally mean?', '["The Spicy Food", "The Akha Way of Life", "The Giant Swing"]', 1, 'It is the total life system governing behavior, morality, and farming.', 1),
	('d7f7a001-0000-0000-0000-000000000002', 'b7f7a001-7777-4a1b-8c1d-000000000001', 'According to belief, who gave the Akha Zang to the people?', '["A foreign king", "The being who created the earth", "A famous chef"]', 1, 'It was given as a complete set of strict guidelines for living correctly.', 2),
	('d7f7a001-0000-0000-0000-000000000003', 'b7f7a001-7777-4a1b-8c1d-000000000001', 'What is the first pillar of Akha Zang?', '["Making money", "The Separation of Spirits and Humans", "Building houses"]', 1, 'Spirits went to the forest, humans to the village; maintaining this separation is vital.', 3),
	('d7f7a001-0000-0000-0000-000000000004', 'b7f7a001-7777-4a1b-8c1d-000000000001', 'What is ''Pyaw''?', '["A musical instrument", "The essential balance between people, spirits, and nature", "A type of rice"]', 1, 'Breaking taboos disturbs the Pyaw, bringing illness or misfortune.', 4),
	('d7f7a001-0000-0000-0000-000000000005', 'b7f7a001-7777-4a1b-8c1d-000000000001', 'How is the Akha Zang transmitted?', '["Through a printed holy book", "Orally through stories, teachings, and daily practice", "Via internet"]', 1, 'It is an oral constitution passed from parents to children without writing.', 5),
	('d7f7a001-0000-0000-0000-000000000006', 'b7f7a001-7777-4a1b-8c1d-000000000001', 'What happens if spirits enter human space according to Akha Zang?', '["They bring wealth", "Illness, misfortune, or imbalance may occur", "Nothing happens"]', 1, 'This is why the Spirit Gate and seasonal offerings are so important.', 6),
	('d7f7a001-0000-0000-0000-000000000007', 'b7f7a001-7777-4a1b-8c1d-000000000001', 'Is Akha Zang just a religion?', '["Yes, purely animism", "No, it is a total life system", "It is just a cookbook"]', 1, 'It is a comprehensive way of life connecting past, present, and future.', 7),
	('d7f7a002-0000-0000-0000-000000000001', 'b7f7a002-7777-4a1b-8c1d-000000000002', 'Who is considered the very first Akha ancestor?', '["Dzoeuh Mah", "Sm Mi O", "Pamee"]', 1, 'Every Akha male must trace his lineage back to Sm Mi O.', 1),
	('d7f7a002-0000-0000-0000-000000000002', 'b7f7a002-7777-4a1b-8c1d-000000000002', 'How many generations back must an Akha male memorize his lineage?', '["5 to 10", "50 to 60", "Just his grandfather"]', 1, 'Memorizing 50-60 generations serves a crucial social and genetic function.', 2),
	('d7f7a002-0000-0000-0000-000000000003', 'b7f7a002-7777-4a1b-8c1d-000000000002', 'What is the strict rule regarding marriage and lineage?', '["You cannot marry outside the village", "You cannot marry if you share a male ancestor within the last 6 generations", "You must marry a cousin"]', 1, 'Sharing an ancestor within 6 generations means you are too closely related to marry.', 3),
	('d7f7a002-0000-0000-0000-000000000004', 'b7f7a002-7777-4a1b-8c1d-000000000002', 'What happens when two people meet on the road in Akha culture?', '["They say ''Goodbye''", "They ask ''Where are you going?'' (Ah ga ei lay)", "They exchange coins"]', 1, 'Asking about your destination is the traditional way of greeting.', 4),
	('d7f7a002-0000-0000-0000-000000000005', 'b7f7a002-7777-4a1b-8c1d-000000000002', 'How do you reply ''I am fine'' in Akha?', '["O doo tu ma", "Jaw sa do mie", "Gher ler her ma"]', 1, '''Jaw sa do mie'' is the correct response to being asked how you are doing.', 5),
	('d7f7a002-0000-0000-0000-000000000006', 'b7f7a002-7777-4a1b-8c1d-000000000002', 'Who holds the second most important position in an Akha village, reflecting respect for tools?', '["The Pa Jee (Blacksmith)", "The Singer", "The Weaver"]', 0, 'The Blacksmith is highly revered for his craftsmanship and creation of essential tools.', 6),
	('d7f7a002-0000-0000-0000-000000000007', 'b7f7a002-7777-4a1b-8c1d-000000000002', 'Why is genealogy considered a ''pillar'' of Akha Zang?', '["It proves who is the richest", "It preserves social order and honors ancestral connections", "It is used for taxes"]', 1, 'Lineage binds the entire Akha community together across borders and time.', 7),
	('d7f7a003-0000-0000-0000-000000000001', 'b7f7a003-7777-4a1b-8c1d-000000000003', 'What is a key rule of etiquette during an Akha communal meal?', '["Eat as fast as possible", "Elders are served first", "Everyone eats in silence"]', 1, 'Serving elders first teaches humility, gratitude, and respect for hierarchy.', 1),
	('d7f7a003-0000-0000-0000-000000000002', 'b7f7a003-7777-4a1b-8c1d-000000000003', 'What role does food play at an Akha wedding?', '["It is sold to guests", "It publicly confirms the couple is part of the wider village network", "It is hidden until midnight"]', 1, 'Sharing a massive communal meal bonds the two families and the village.', 2),
	('d7f7a003-0000-0000-0000-000000000003', 'b7f7a003-7777-4a1b-8c1d-000000000003', 'What do neighbors traditionally bring to a grieving family during a funeral?', '["Gold coins", "Food, rice, or animals to support the family", "New clothes"]', 1, 'The village shares the burden so no family faces loss or hunger alone.', 3),
	('d7f7a003-0000-0000-0000-000000000004', 'b7f7a003-7777-4a1b-8c1d-000000000003', 'Who must approve a marriage union before preparations begin?', '["The Mayor", "Elders from both families", "The Blacksmith"]', 1, 'Elders ensure that family lines, customs, and social relationships are respected.', 4),
	('d7f7a003-0000-0000-0000-000000000005', 'b7f7a003-7777-4a1b-8c1d-000000000003', 'How are dishes consumed during a traditional meal?', '["Everyone gets their own separate plate", "Food is shared from common dishes", "Men and women eat in different villages"]', 1, 'Sharing from common dishes encourages togetherness and equality.', 5),
	('d7f7a003-0000-0000-0000-000000000006', 'b7f7a003-7777-4a1b-8c1d-000000000003', 'What does sharing meals at a funeral represent?', '["A celebration of wealth", "A reminder that life continues and offers emotional solace", "A requirement to pay off debt"]', 1, 'Just as ancestors once ate with the community, the living gather to honor their memory.', 6),
	('d7f7a003-0000-0000-0000-000000000007', 'b7f7a003-7777-4a1b-8c1d-000000000003', 'What does the kitchen become for young Akha people?', '["A place to play", "A living classroom where values and traditions are passed down", "A place to hide"]', 1, 'By watching and helping, young people learn the Akha Way organically.', 7),
	('2f952c15-28f4-44ca-9e10-6e2c22a8818d', '9124c8b5-9c9f-47e2-bef9-0171964dd415', 'Which type of papaya is used for the traditional Som Tum salad?', '["Green (unripe) papaya", "Yellow (ripe) papaya", "Orange papaya"]', 0, 'For cooking and salads, the papaya must be green and unripe to maintain its crunch.', 1),
	('c5b8a081-2a82-4397-b7be-0f00d5314ccc', '9124c8b5-9c9f-47e2-bef9-0171964dd415', 'What is the traditional tool used to make Papaya Salad?', '["Electric blender", "Mortar and pestle", "Food processor"]', 1, 'The salad is traditionally hand-pounded using a mortar and pestle to release the flavors.', 2),
	('a4ec585d-42b5-44af-a1ff-2aa2ee51c25d', '9124c8b5-9c9f-47e2-bef9-0171964dd415', 'Which enzyme found in raw papaya significantly improves digestion?', '["Papain", "Amylase", "Lipase"]', 0, 'Raw papaya is rich in papain enzymes that aid in digestion and metabolism.', 3),
	('1e776199-7084-4fe0-a017-edaf9b264fe7', '2300f6b6-3116-4083-8f61-2bce612429b4', 'What is the ideal oil temperature for deep frying spring rolls?', '["50°C", "100°C", "200°C"]', 1, 'The oil should be brought up to 100°C for perfect deep-frying.', 1),
	('11bea4a2-6bf9-4872-ace5-ac56f9139860', '2300f6b6-3116-4083-8f61-2bce612429b4', 'How can you easily test if the oil is hot enough for frying?', '["Drop a piece of garlic in it", "Drop water in it", "Wait for it to smoke"]', 0, 'If a small piece of garlic floats on the surface, the oil is ready for deep-frying.', 2),
	('27718c26-d3f5-4009-be94-1051b1329f62', '2300f6b6-3116-4083-8f61-2bce612429b4', 'What shape should the wrapper be folded into before rolling?', '["A circle", "A triangle", "An envelope"]', 2, 'Fold the bottom, left, and right sides to make an envelope shape, then roll it tightly.', 3),
	('5a57ba72-83c6-4190-9168-63da2b4302a1', '24216dc7-2b2d-4abb-9b47-82d0f17f41ba', 'During which historical event was Pad Thai heavily promoted?', '["World War I", "World War II", "The Cold War"]', 1, 'During WWII, Thailand suffered a rice shortage, and the government promoted noodles, leading to the creation of Pad Thai.', 1),
	('6e1b6653-163a-482f-8e92-cb135ae11632', '24216dc7-2b2d-4abb-9b47-82d0f17f41ba', 'What does the word "Pad" mean in Thai?', '["Boiled", "Sweet", "Stir-fry"]', 2, '"Pad" is the Thai word for stir-fry.', 2),
	('38b1f075-8da3-4e9d-a3ab-7b5f99f883ca', '24216dc7-2b2d-4abb-9b47-82d0f17f41ba', 'Which ingredient gives Pad Thai its signature tangy flavor?', '["Tamarind sauce", "Tomato ketchup", "Coconut milk"]', 0, 'Tamarind sauce provides the classic sweet and sour tang of Pad Thai.', 3),
	('5c5a2ce6-2348-41a6-8bdf-3434575498cc', '3aff89a5-fe78-47a0-8acf-f788961c74be', 'What type of chili is traditionally used for Thai Red Curry?', '["Fresh green chilies", "Sun-dried red chilies", "Black pepper"]', 1, 'Red curry paste is traditionally made from sun-dried red Anaheim peppers.', 1),
	('6a5887e0-daab-4834-ad41-969163ef3e4f', '3aff89a5-fe78-47a0-8acf-f788961c74be', 'What ingredient sweetens Green Curry and gives it a rich color?', '["Palm sugar", "Honey", "Coconut milk"]', 2, 'Coconut milk sweetens the curry and turns it into a rich, creamy green color.', 2),
	('4a261cd1-0d4f-4031-a07b-9295b83804cb', '3aff89a5-fe78-47a0-8acf-f788961c74be', 'Which parts of the Kaffir Lime are used in Thai cooking?', '["Only the juice", "The leaves and the skin", "The roots and seeds"]', 1, 'We use the double-lobed leaves and the bumpy skin (zest) for their intense citrus perfume.', 3),
	('0050b4cb-1d5f-4214-b78b-19fcf73b4985', '21cd0f95-85fd-40a3-a78a-2df6a0f1738e', 'Panang curry has culinary influences from which regions?', '["Indian and Malay", "Chinese and Japanese", "Vietnamese and Lao"]', 0, 'Panang has Indian and Malay influences, often using Garam Masala powder.', 1),
	('3623b7d5-5f1d-45a7-b7b2-28b6dff54027', '21cd0f95-85fd-40a3-a78a-2df6a0f1738e', 'What makes Panang curry perfect for meat lovers?', '["It contains no vegetables", "It is served raw", "It is only made with beef"]', 0, 'Traditional Panang is a thick, rich curry served with meat and no vegetables.', 2),
	('43a661e2-4c44-4381-a542-5776e5c95c1c', '21cd0f95-85fd-40a3-a78a-2df6a0f1738e', 'Which nut is used to give Panang its signature thick texture?', '["Almonds", "Cashews", "Roasted peanuts"]', 2, 'Roasted peanuts are pounded into the sauce for a thick, rich, and nutty flavor.', 3),
	('6d53ff81-bc0e-4b13-bcf8-23abe00d134b', 'ee2171ee-5dd3-41b8-82d7-af23a5eeef20', 'Massaman curry features which imported dry spices?', '["Cinnamon, Cardamom, and Star Anise", "Basil, Mint, and Cilantro", "Ginger, Garlic, and Shallots"]', 0, 'It uses Persian dry spices like Cinnamon, Cardamom, and Star Anise.', 1),
	('917d8220-ef3c-4b9d-b5f4-60e15e05a079', 'ee2171ee-5dd3-41b8-82d7-af23a5eeef20', 'Which root vegetable is a staple in Massaman Curry?', '["Carrot", "Potato", "Radish"]', 1, 'Massaman is traditionally simmered with soft potatoes.', 2),
	('85045d82-fbc3-4a88-9c38-b753e08882d9', 'ee2171ee-5dd3-41b8-82d7-af23a5eeef20', 'Massaman Curry originally comes from which region?', '["Northern Thailand", "Southern Thailand", "Eastern Thailand"]', 1, 'Massaman Curry originally comes from the southern region of Thailand and Malay cuisine.', 3),
	('4a9964e7-dcff-452c-8910-523b96ace97c', '4edabfc0-df6c-4c6a-b680-3fabcd080fbb', 'In the Akha language, what does "Sapi" mean?', '["Tomato", "Chili", "Salt"]', 1, '"Sapi" means chilies, and "Thong" means pounded.', 1),
	('ce98bf67-6752-4fef-a322-8b75fd888779', '4edabfc0-df6c-4c6a-b680-3fabcd080fbb', 'What makes the "Luu Neh" version of Sapi Thong unique?', '["It is frozen", "Ingredients are roasted over charcoal until blistered", "It uses no chilies"]', 1, '"Luu Neh" means to roast. Chilies and tomatoes are charred over an open fire.', 2),
	('ab9e6d7f-73e8-48f0-86a0-e9fa510b1e00', '4edabfc0-df6c-4c6a-b680-3fabcd080fbb', 'What is "Ahchi" used in fermented Akha dips?', '["Wild mushrooms", "Dried river fish", "Fermented soybean sheets"]', 2, 'Ahchi are fermented soybean sheets, toasted until crispy for deep umami flavor.', 3),
	('f80c2bc1-8d9d-4675-8dec-5c8a4c64b66d', 'b149beb4-a7ea-4ef8-a339-b90f94f3a843', 'Which special herb is used in the Akha Mountain Fresh Salad?', '["Mountain Coriander (Phak Chi Doi)", "Sweet Basil", "Lemongrass"]', 0, 'This salad uses wild Mountain Coriander, known as Phak Chi Doi.', 1),
	('e9344676-7476-413a-9b32-e176a6cecf70', 'b149beb4-a7ea-4ef8-a339-b90f94f3a843', 'How is the cucumber prepared for this salad?', '["Finely diced with a knife", "Gently bruised in a wooden mortar", "Boiled until soft"]', 1, 'The cucumber is gently bruised in a wooden mortar to absorb the dressing while keeping its crunch.', 2),
	('1dc5aaa6-4132-49c9-b37f-db5e602b9a8b', 'b149beb4-a7ea-4ef8-a339-b90f94f3a843', 'What type of oil is used in the traditional Akha salad dressing?', '["Olive oil", "Sesame oil", "No oil is used"]', 2, 'The traditional Akha Mountain Fresh Salad is served without any oil.', 3),
	('49061261-50b0-468c-a75c-508b7232c280', 'eeeada00-df51-41c0-8c64-46eec2c26db0', 'Which ingredient is strictly forbidden in the traditional Spirit Detox Soup?', '["Meat", "Water", "Herbs"]', 0, 'Meat is strictly forbidden to maintain the spiritual purity of the broth.', 1),
	('dd80bbf2-8e28-4802-9550-74b4d57284d9', 'eeeada00-df51-41c0-8c64-46eec2c26db0', 'What is the main vegetable used in this restorative tonic?', '["Pumpkin", "Winter Melon (Fuk Kiow)", "Carrot"]', 1, 'The soup uses Winter Melon, ginger, and smashed herbs.', 2),
	('df2aa905-a200-45cb-b192-188ff5720155', 'eeeada00-df51-41c0-8c64-46eec2c26db0', 'What is the primary health benefit of the chili capsaicin in Akha soups?', '["It helps you sleep", "It boosts circulation and clears respiratory paths", "It builds muscle"]', 1, 'Capsaicin boosts circulation and has strong anti-inflammatory effects.', 3),
	('d932c24d-b4e8-4252-847d-a032d5bb7dc9', '3012dcb1-3079-4500-99fa-0185b187120e', 'Which mango variety is traditionally used for Mango Sticky Rice?', '["Fuji", "Granny Smith", "Nam Dok Mai"]', 2, 'Sweet yellow mango, usually the Nam Dok Mai variety, is used for sticky rice.', 1),
	('1e17800c-f8cc-438b-8354-26ea79507c5c', '3012dcb1-3079-4500-99fa-0185b187120e', 'Why is green papaya used in cooking rather than yellow papaya?', '["It is sweeter", "It has a crisp, neutral flavor that soaks up dressings", "It is softer"]', 1, 'Green papaya is unripe, offering a crunchy texture perfect for Som Tum.', 2),
	('553c3bbe-b58e-4b05-b07e-8cee946c5bd3', '3012dcb1-3079-4500-99fa-0185b187120e', 'In Thai cooking, pineapple is a crucial ingredient for which dish?', '["Green Curry", "Sweet and Sour Chicken", "Pad Thai"]', 1, 'Pineapple provides a citrusy kick in Thai Sweet and Sour Chicken.', 3),
	('2cfcb283-89f0-41b5-b805-c7ef7a436359', '86f0d205-ac5e-4c33-bdaf-e52d13f22a9f', 'Which part of the lemongrass stalk is used for cooking?', '["The green leafy tips", "The roots", "The tender white base"]', 2, 'We use the tender white base, crushed to release a fresh, lemony aroma.', 1),
	('28413e9b-b154-4267-a131-e1f6cb75e786', '86f0d205-ac5e-4c33-bdaf-e52d13f22a9f', 'How does Galangal differ from regular ginger?', '["It is much sweeter", "It has a distinct citrusy, pine-like flavor", "It is black in color"]', 1, 'Galangal is paler, harder, and has a distinct citrusy, pine-like flavor.', 2),
	('ef0face3-5094-45fb-9103-acff4edc0fa7', '86f0d205-ac5e-4c33-bdaf-e52d13f22a9f', 'What flavor profile defines Thai Sweet Basil (Horapha)?', '["Licorice/anise flavor", "Peppery and spicy", "Sour and bitter"]', 0, 'Sweet Basil has a distinct licorice or anise-like taste.', 3),
	('7d25da5f-446b-4042-8d87-eb9a7256a604', '2e0ba1ba-1265-4267-927b-dbc4cdc45c78', 'What shape is Star Anise?', '["A round ball", "An eight-pointed star", "A long stick"]', 1, 'It is an eight-pointed star seed with a strong licorice flavor.', 1),
	('1e89ada2-ea41-47e8-a5a1-ae2f7e3de89e', '2e0ba1ba-1265-4267-927b-dbc4cdc45c78', 'What effect does Sichuan Pepper (Mak Khen) have on the palate?', '["Extreme sweetness", "A numbing, citrusy heat", "A cooling sensation"]', 1, 'Known as Mak Khen in Akha, it provides a unique numbing and citrusy heat.', 2),
	('4c773f6f-20bd-485c-b851-4877b04b489e', '2e0ba1ba-1265-4267-927b-dbc4cdc45c78', 'Which fresh root gives Northern curries a distinctive bright orange color?', '["Fresh Turmeric", "White Ginger", "Galangal"]', 0, 'Fresh turmeric is a bright orange root used for coloring and health benefits.', 3),
	('85f950b6-bc46-4915-9eaa-be3c581245d2', '854a35f0-1421-424f-b1ba-017ce1e04a37', 'Why do Akha cooks pound herbs instead of using an electric blender?', '["Blenders are too loud", "Pounding crushes cell walls to release essential oils", "Pounding makes it sweeter"]', 1, 'Pounding releases deep flavors and medicinal properties that blending (which just cuts) cannot achieve.', 1),
	('bc2b9b8e-2896-40cf-ac68-d822f91364de', '854a35f0-1421-424f-b1ba-017ce1e04a37', 'What material is best for a mortar used to make curry pastes?', '["Wood", "Plastic", "Stone"]', 2, 'A heavy stone mortar is required to properly grind hard roots and spices into a fine paste.', 2),
	('f802bcf3-aee4-4812-8b59-daaccfa795b8', '854a35f0-1421-424f-b1ba-017ce1e04a37', 'What is the Akha philosophy regarding the speed of pounding Sapi Thong?', '["As fast as possible", "Pounded slowly by hand", "Only pounded once"]', 1, 'Ingredients are pounded slowly by hand to keep the texture and smell strong.', 3),
	('cfbee67e-a91d-4eaa-813c-8e847a1bdff4', '4b68db87-9d13-48cb-8e1c-aa8195ff7a4d', 'Which Thai curry paste relies primarily on DRY chilies?', '["Green Curry", "Red Curry", "Jungle Curry"]', 1, 'Red curry is made using sun-dried red Anaheim or Cayenne peppers.', 1),
	('3a50c870-92d9-43ad-86f6-424128bcd163', '4b68db87-9d13-48cb-8e1c-aa8195ff7a4d', 'Which Thai curry relies on FRESH chilies for its color and flavor?', '["Green Curry", "Massaman Curry", "Panang Curry"]', 0, 'Green curry uses fresh green chilies and coriander stems.', 2),
	('04b4acb4-9035-467e-8732-ff3641a6ad01', '4b68db87-9d13-48cb-8e1c-aa8195ff7a4d', 'In traditional Thai cooking, garlic is almost always used in what form?', '["Dried garlic powder", "Fresh cloves", "Pickled garlic"]', 1, 'Fresh garlic cloves are an essential, daily fresh ingredient in Thai kitchens.', 3),
	('e343875b-0b23-4e55-881c-260e9a93cae3', '195a1d2a-47ae-4950-a1c0-e12a8433e2b9', 'Which ingredient is the primary source of SALTiness in traditional Thai cooking?', '["Table salt", "Fish sauce", "Cheese"]', 1, 'Fish sauce (fermented anchovy extract) provides the essential salt and umami.', 1),
	('05ca5cbd-b6ac-4685-8138-0447d99976ef', '195a1d2a-47ae-4950-a1c0-e12a8433e2b9', 'Which fruit pod provides the signature SOUR tang in Pad Thai?', '["Lemon", "Tamarind", "Mango"]', 1, 'Tamarind is a sour fruit pod used to make the tangy paste for Pad Thai.', 2),
	('bab91ce2-d6fc-4d6e-985a-27be5728d91f', '195a1d2a-47ae-4950-a1c0-e12a8433e2b9', 'What is traditionally used to add SWEETness instead of refined white sugar?', '["Palm sugar", "Agave syrup", "Maple syrup"]', 0, 'Palm sugar, made from coconut palm sap, provides a complex caramel sweetness.', 3),
	('af06f937-4742-48fd-84a3-5965de9278bc', 'c41d35aa-2f8f-48f2-9f2e-87bd9f810758', 'In traditional Akha society, who are the primary foragers of the forest?', '["The men", "The women", "The children"]', 1, 'While men hunt, Akha women are the primary foragers of wild plants and herbs.', 1),
	('4d8245eb-dbe2-4784-8a09-e682f116e2a7', 'c41d35aa-2f8f-48f2-9f2e-87bd9f810758', 'What is the Akha rule for foraging in the wild?', '["Take everything you find", "Take only what is needed and harvest in season", "Burn the plants after picking"]', 1, 'Akha people forage with respect, taking only what is needed to protect nature.', 2),
	('3d0ee857-ed33-4836-9237-40de15b6396f', 'c41d35aa-2f8f-48f2-9f2e-87bd9f810758', 'According to the Akha saying, how many things in the jungle can you NOT eat?', '["Three", "Ten", "Everything is edible"]', 0, 'There are only three things in the jungle you can not eat, and nobody knows what they are!', 3),
	('fe408826-23b1-4686-9ccb-906fdd093bb7', 'fad7e3f8-8f3e-425c-b0f1-30753bd20d0f', 'What are "Non Rot Duan"?', '["Wild mushrooms", "Dried edible insects", "River fish"]', 1, 'They are a traditional highland protein source made from dried insects.', 1),
	('ce7c5f3e-2c4e-4b99-8c14-15b8c4d6b584', 'fad7e3f8-8f3e-425c-b0f1-30753bd20d0f', 'How do the Akha typically utilize large livestock like black pigs?', '["Eaten daily for breakfast", "Reserved for ceremonial sacrifices or special guests", "Used only for milk"]', 1, 'Large livestock is highly valued and reserved for ceremonies, not daily consumption.', 2),
	('5df8ce5c-b49c-4b93-813d-9e892b07705f', '9301aad1-8b95-467d-9262-4017cbe633f1', 'What part of the banana tree is used in salads and tastes similar to artichoke?', '["The roots", "The banana blossom (flower)", "The trunk"]', 1, 'The blossom (Hua Plee) is edible and has a texture and taste similar to artichoke.', 1),
	('e96e3ff7-0f03-45da-9861-7bde60fa842e', '9301aad1-8b95-467d-9262-4017cbe633f1', 'What color is the edible pumpkin flower (Dok Fak Thong)?', '["Red", "Blue", "Yellow"]', 2, 'It is a bright yellow edible flower from the pumpkin plant.', 2),
	('6b9179c8-ed6e-4986-b6b9-b8582609968d', '9301aad1-8b95-467d-9262-4017cbe633f1', 'Why are Roselle leaves added to Akha soups?', '["To add sweetness", "To add natural acidity and sourness", "To make it spicy"]', 1, 'Roselle leaves are naturally sour and add a refreshing acidity to broths.', 3),
	('0cbfd8b5-687b-4b44-bf6a-ec63f6fbe088', '0ac87dbb-193b-4104-893e-1b282c80c91e', 'How close is Thai Akha Kitchen to the South Gate of Chiang Mai?', '["A 5-minute walk", "A 1-hour drive", "It is outside the city"]', 0, 'Our cooking school is conveniently located just a 5-minute walk from Chiang Mai South Gate.', 1),
	('c1eb842c-86a7-4a63-86c4-063635a61c1f', '0ac87dbb-193b-4104-893e-1b282c80c91e', 'What shape is the ancient walled city center of Chiang Mai?', '["A perfect circle", "A square", "A triangle"]', 1, 'The Old City is surrounded by a square moat and ancient brick walls.', 2),
	('dcc1bb96-4531-4c0c-8624-ea94995161a8', '0ac87dbb-193b-4104-893e-1b282c80c91e', 'Which pickup zone color covers the Chiang Mai Old City area?', '["Red Zone", "Blue Zone", "Green Zone"]', 2, 'The Green Area is the standard pickup zone covering the Old City.', 3),
	('53794cd7-fb9d-4cab-9012-ce21e8ddd869', '5491b091-00e6-4ccf-b08a-9cf97f8ab36a', 'Which temple serves as the morning market meeting point for the school?', '["Wat Phra Singh", "Wat Pan Whaen", "Wat Chedi Luang"]', 1, 'We meet near the big white pagoda at Wat Pan Whaen for the morning market tour.', 1),
	('78a2da5d-26f0-4f3c-b40b-59be72178cf9', '5491b091-00e6-4ccf-b08a-9cf97f8ab36a', 'What distinct architectural feature helps you find the Wat Pan Whaen meeting point?', '["A giant golden Buddha", "A big white Pagoda", "A red wooden bridge"]', 1, 'Walk inside the temple and you will see a big white Pagoda where our crews will meet you.', 2),
	('15f61720-ca3a-4f62-b24b-b82801cd71a8', '5491b091-00e6-4ccf-b08a-9cf97f8ab36a', 'What is the general etiquette for clothing when entering a Thai temple?', '["Wear a swimsuit", "Cover your shoulders and knees", "Wear a hat"]', 1, 'Temples are sacred spaces; shoulders and knees must be covered to show respect.', 3),
	('f14a7a9e-300c-4a83-9533-dea57d3d383b', '8bd97584-7a61-493c-985b-975abc232891', 'At what time does the Morning Market Visit Tour begin?', '["7:00 am", "9:00 am", "12:00 pm"]', 1, 'The Market Tour starts promptly at 9:00 am.', 1),
	('8f223556-0e76-4ec2-8b3a-383e6b814f8e', '8bd97584-7a61-493c-985b-975abc232891', 'How can you recognize the Thai Akha Kitchen crew at the meeting point?', '["They hold a red flag", "They wear Thai Akha Kitchen aprons and hold a sign", "They blow a whistle"]', 1, 'Our driver will be holding a Thai Akha Kitchen pick-up sign or wearing our uniform.', 2),
	('46cfe2e3-fe4b-4a9c-9997-1c77579cc2f9', '8bd97584-7a61-493c-985b-975abc232891', 'What Thai phrase describes finding the same products at different prices in the market?', '["Cheap cheap", "Same same, but different", "Good price"]', 1, 'You can see the same products being sold at all different prices; we call this "same same, but different".', 3),
	('666f9ae7-7dbb-4cee-9c9b-04cdd3a0ff1e', '2b7ac167-dfdb-4706-9cbe-420f4beec865', 'What is "Lanna"?', '["A type of food", "The traditional language and culture of Northern Thailand", "A river in Chiang Mai"]', 1, 'Lanna was an ancient northern kingdom, and its language is still used daily in Chiang Mai.', 1),
	('b041edaa-8462-4556-9828-305252fe43e3', '2b7ac167-dfdb-4706-9cbe-420f4beec865', 'What does the standard Thai greeting "Sawasdee kha" mean?', '["Thank you", "Hello", "Delicious"]', 1, 'Sawasdee kha (for women) or khrap (for men) is the universal Thai greeting for Hello.', 2),
	('c18b39fd-e466-414c-a4a9-4dfe4e44e169', '2b7ac167-dfdb-4706-9cbe-420f4beec865', 'How many languages does Chef Niti speak fluently?', '["One", "Two", "Four"]', 2, 'Chef Niti is fluent in four languages: Akha, Lanna, Thai, and English.', 3),
	('0b5111e8-3e78-431b-be25-0ac8de96db6e', '50dfdec4-8853-4814-be97-d0265a260e85', 'Which of these is considered the ultimate classic Thai street food?', '["Massaman Curry", "Pad Thai", "Tom Kha Gai"]', 1, 'Pad Thai is considered classic fast food and the national street-food dish of Thailand.', 1),
	('e7099925-8b69-475a-9554-46b9ec99c3b1', '50dfdec4-8853-4814-be97-d0265a260e85', 'How is food traditionally served and eaten at a Thai table?', '["Everyone gets their own separate meal", "Dishes are shared communally in the center of the table", "Only the elders eat"]', 1, 'Thai people share their food. There is usually soup, curry, and stir-fry shared among everyone.', 2),
	('1e0c033b-d4fd-4ded-b726-a4b2422659cf', '50dfdec4-8853-4814-be97-d0265a260e85', 'Do authentic local Thai restaurants usually offer a dessert menu after the meal?', '["Yes, always", "No, sweets are usually eaten as snacks during free time", "Only on Sundays"]', 1, 'Authentic Thai restaurants rarely serve dessert; sweets (Khong wan) are reserved for sweet shops and free time.', 3),
	('1d3f8a4e-9fcf-4203-974e-ea09a52be021', 'b9de9c3b-fb06-4307-95c6-623ade30ed50', 'If your hotel is in the Pink Zone, what time should you be ready for morning pickup?', '["8:20 am", "8:40 am", "9:00 am"]', 1, 'The Pink Zone is an extended pickup area requiring you to be ready at 8:40 am.', 1),
	('1e31c58a-1e04-4b23-b223-0d3256216da4', 'b9de9c3b-fb06-4307-95c6-623ade30ed50', 'What does the Yellow Zone indicate for our transport drivers?', '["No pickup available", "High traffic zone requiring an earlier 8:20 am pickup", "Airport drop-off only"]', 1, 'The Yellow Area is a high traffic zone, so we pick you up earlier to avoid delays.', 2),
	('31b241d8-fa6f-428c-9d55-e663b8116609', 'b9de9c3b-fb06-4307-95c6-623ade30ed50', 'Does Thai Akha Kitchen offer free direct pickup from the Airport?', '["Yes, at Gate 2", "No, you must arrange a Grab taxi (approx 150-200 THB)", "Yes, but only at night"]', 1, 'Free pickup is not included from the airport. We suggest arranging a Grab taxi to meet us.', 3),
	('75e48939-f8fb-41d5-b4ae-600734c99b7e', 'b7e3060a-15d0-406b-b770-ec6a4922c970', 'Which Thai province was the first settlement for Akha immigrants and remains their heartland?', '["Phuket", "Bangkok", "Chiang Rai"]', 2, 'The Akha began settling in Thailand in the early 1900s, first in the mountains of Chiang Rai.', 1),
	('51929cb8-5c35-4765-b71f-774b7586f1fc', 'b7e3060a-15d0-406b-b770-ec6a4922c970', 'The famous "Golden Triangle" is the border meeting point of which three countries?', '["Thailand, Laos, and Myanmar", "Thailand, Vietnam, and Cambodia", "China, India, and Thailand"]', 0, 'The Golden Triangle is where the borders of Thailand, Laos, and Myanmar meet.', 2),
	('7bd3f957-ebcf-4169-ac72-f69bae5fe11b', 'b7e3060a-15d0-406b-b770-ec6a4922c970', 'Where did the Akha ancestors originally migrate from centuries ago?', '["The Vietnamese Coast", "The Tibetan Plateau and Yunnan", "The Indonesian Islands"]', 1, 'Ancestral roots trace back to the Tibetan Plateau and Yunnan province in China.', 3),
	('7e3b7430-8765-45f4-b127-ded7676a188a', '5da1929e-7761-4b27-9784-3d94ab3bba10', 'Which crop did Akha communities historically grow before transitioning to coffee?', '["Corn", "Opium", "Wheat"]', 1, 'Many Akha communities successfully transitioned from opium cultivation to sustainable coffee.', 1),
	('2634158d-43e1-48c2-adca-f8c8be3fefb7', '5da1929e-7761-4b27-9784-3d94ab3bba10', 'What type of coffee bean is primarily grown in the Northern Thai highlands?', '["Robusta", "Liberica", "Arabica"]', 2, 'The high-altitude environments of the North are perfect for specialty Arabica coffee.', 2),
	('9bb8251c-bde2-479d-a601-b91f62367377', '5da1929e-7761-4b27-9784-3d94ab3bba10', 'Which famous Chiang Mai café showcases fair-trade Akha coffee?', '["Starbucks", "Akha Ama Coffee", "Cafe Amazon"]', 1, 'Akha Ama Coffee is a flagship café showcasing specialty beans and the story of Akha farmers.', 3),
	('492bf6f9-db58-4891-b64e-8de78ecc9e5d', 'edd7e4ad-2015-4fad-b6c2-1f783cbfb7d5', 'Approximately how many different ethnic minority groups (Hill Tribes) live in Northern Thailand?', '["Three", "Twelve", "Fifty"]', 1, 'There are 12 different groups of ethnic minority people living in Northern Thailand.', 1),
	('cc1377ea-8eff-4b93-bfc2-989de2585740', 'edd7e4ad-2015-4fad-b6c2-1f783cbfb7d5', 'What is the approximate Akha population currently living in Thailand?', '["10,000", "80,000", "500,000"]', 1, 'There are now about 80,000 Akha people living in small villages in the mountains of Thailand.', 2),
	('07f1a926-d55c-44d3-ad6e-f56600a59cc6', 'edd7e4ad-2015-4fad-b6c2-1f783cbfb7d5', 'Besides Thailand and China, which neighboring countries have significant Akha populations?', '["Malaysia and Singapore", "Myanmar and Laos", "Cambodia and Vietnam"]', 1, 'Myanmar (Shan State) and Laos have large Akha populations living near the borders.', 3);
