	('religion-01', 'religion_beliefs_puck.mp3', 'akha-history', 'https://mtqullobcsypkqgdkaob.supabase.co/storage/v1/object/public/akha-history/religion_beliefs_puck.mp3', 'The Akha Cosmos: Religion, Belief, and Taboo - Narration', 'Voice narration by Puck.', NULL, 'audio/mpeg', NULL, NULL, '2026-04-01 19:51:45.775914+00', '2026-04-04 20:43:04.014361+00', 'e4617560-41c2-4666-ae57-21d1aa397e7c', NULL),
